// Original worked tutorials. Hardware examples explicitly select their paging mode.
const ref = (label, url, section) => ({ label, url, section });
const ostep = (chapter, file) => ref(`OSTEP: ${chapter}`, `https://pages.cs.wisc.edu/~remzi/OSTEP/${file}.pdf`, chapter);
const intel = ref('Intel Software Developer Manuals', 'https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html', 'Volume 3A, chapters 4 and 6: paging and exceptions');
const osc = ref('Operating System Concepts, tenth edition', 'https://www.os-book.com/OS10/slide-dir/index.html', 'Chapters 9 and 10: Main Memory and Virtual Memory');
const acpi = ref('ACPI system address map interface', 'https://uefi.org/specs/ACPI/6.5/15_System_Address_Map_Interfaces.html', 'Section 15.1: INT 15h, E820h');
const kernelMemory = ref('Linux physical memory documentation', 'https://docs.kernel.org/mm/physical_memory.html', 'Nodes, zones, and page allocation');
const kernelTables = ref('Linux page table documentation', 'https://docs.kernel.org/mm/page_tables.html', 'Page table hierarchy and folding');
const kernelTlb = ref('Linux cache and TLB flushing', 'https://docs.kernel.org/core-api/cachetlb.html', 'TLB flush interfaces');
const elf = ref('System V ELF ABI', 'https://refspecs.linuxfoundation.org/elf/gabi4+/ch5.pheader.html', 'Program headers and loadable segments');
const p = (...paragraphs) => ({ type: 'prose', paragraphs });
const table = (caption, columns, rows) => ({ type: 'table', caption, columns, rows });
const trace = (caption, columns, rows) => ({ type: 'trace', caption, columns, rows });
const code = (title, language, code, notes) => ({ type: 'code', title, language, code, notes });
const exercise = (title, prompt, tasks, solution, checks) => ({ type: 'exercise', title, prompt, tasks, solution, checks });
const steps = (title, pairs) => ({ type: 'steps', title, items: pairs.map(([title, text]) => ({ title, text })) });
const topic = (id, sectionId, title, intro, blocks, references) => ({ id, sectionId, title, intro, blocks, references });

export const memoryHandbook = {
  'memory-discovery': [
    topic('memory-address-ownership', 'ownership', 'Five different meanings of an address', [
      'Before allocating anything, distinguish a byte address, a frame number, a pointer, a file offset, and an ownership claim. A hexadecimal number carries none of this information by itself. Most early memory bugs come from combining two of these quantities as if they had the same units.',
      'This course kernel uses 32-bit x86 protected mode with flat segments and, later, ordinary 4 KiB paging. Firmware still reports 64-bit physical ranges. Keep that information in 64-bit integers until you explicitly intersect it with the physical range your kernel can manage.'
    ], [
      table('Write the units beside each value', ['Quantity', 'Example', 'Meaning and valid operation'], [
        ['Physical byte address', '0x0034507A', 'Location on the physical address map; may denote RAM, device memory, or a hole.'],
        ['Physical frame number', '0x345', '4096-byte unit. Its base address is PFN << 12 = 0x00345000.'],
        ['Virtual byte address', '0x0040307A', 'Process-visible address translated by the current page tables.'],
        ['Kernel pointer', '(void *)0xC034507A', 'A usable C pointer only if this virtual address is mapped with suitable permissions.'],
        ['ELF file offset', '0x207A', 'Byte position inside an executable file; it does not identify a RAM frame.'],
        ['Owned interval', '[0x00345000, 0x00346000)', 'Allocator promise: one owner may modify or release this complete frame.']
      ]),
      p('A half-open interval `[start, end)` includes its first byte and excludes its end. Its length is `end - start`; adjacent intervals `[a,b)` and `[b,c)` do not overlap. This convention removes special cases from zero-length ranges, alignment, array indexing, and subtraction. At the top of a 32-bit address space, the exclusive end is `0x100000000`, so range arithmetic requires a wider type even when every individual usable address fits in 32 bits.',
        'Firmware availability and allocator availability are separate states. A firmware region labeled usable may currently hold the kernel image, boot information, an initial stack, page tables, or the allocator bitmap itself. Treat all frames as unavailable first. Then release only frames that are inside a validated usable region and outside every reservation. This direction of construction ensures that an unrecognized hole stays unavailable.',
        'Ownership has a lifetime. A loader scratch buffer may become reclaimable after its contents are copied. The live kernel stack cannot become reclaimable while instructions still use it. An ACPI reclaimable region requires a deliberate policy after the needed tables are preserved. Record a reason and a release condition for each reservation, so reclamation becomes a controlled state change.'),
      exercise('Account for one frame', 'Physical frame 0x345 is firmware-usable and contains the current page directory. A process asks for a frame.', ['Decide whether the PMM can return 0x345.', 'Explain what must happen before this frame can be reused.', 'Explain why casting 0x00345000 to a C pointer might fail after enabling paging.'], ['The frame remains reserved because a live page directory owns it.', 'Switch every relevant CPU away from the directory, retire cached translations as required, and prove that software walkers no longer hold references before releasing it.', 'A physical number has no implied virtual mapping. The kernel needs an identity mapping, a direct mapping, or a temporary mapping to access the bytes.'], ['Firmware type alone never authorizes reuse.', 'The answer identifies both hardware and software references.'])
    ], [acpi, kernelMemory]),
    topic('memory-e820-protocol', 'e820', 'Collect the BIOS map as a checked protocol', [
      'E820 is a BIOS real-mode interface that returns a sequence of address-range descriptors. Your protected-mode C kernel should consume a stable loader-owned copy of those descriptors. It should not attempt to call a BIOS interrupt as an ordinary protected-mode function.',
      'The loader needs both a protocol loop and a bounded output buffer. Every iteration can fail, every length must be checked, and a continuation token is opaque. A partially collected map needs an explicit failure policy; silently treating omitted memory as available creates corruption.'
    ], [
      table('Descriptor bytes, decoded without native-structure assumptions', ['Byte offset', 'Width', 'Field'], [['0','8','Little-endian physical base'],['8','8','Little-endian byte length'],['16','4','Range type'],['20','4','Extended attributes, when returned']]),
      steps('Bounded collection in the BIOS loader', [
        ['Prepare a fresh request', 'Set EAX = 0xE820, EDX = 0x534D4150 (SMAP), ECX to the available descriptor size, and ES:DI to writable real-mode memory. Use EBX = 0 on the first call. Reinitialize request registers for each call.'],
        ['Call and validate', 'Execute INT 0x15. Check carry before accepting output, require the returned EAX signature, and require at least 20 bytes. Interpret only bytes actually returned. Preserve the BIOS continuation value unchanged for the next request.'],
        ['Store conservatively', 'Reject a zero-length descriptor from allocation accounting. Check capacity before copying another record. Preserve the type and attributes so later normalization has the full evidence.'],
        ['Finish deliberately', 'A returned EBX of zero marks the final descriptor. Firmware may also signal completion by carry on a later call. Distinguish this from failure on the first call. Stop with a safe diagnostic if the buffer or iteration bound is exhausted.']
      ]),
      p('Do not sum all lengths and call that number RAM. The map may contain gaps, reserved ranges, duplicated or overlapping entries, and addresses beyond the CPU mode you support. A machine with a usable range ending at 4 GiB can still have substantially less usable memory because devices occupy part of the physical address space.',
        'Range type 1 is the ordinary candidate for general-purpose allocation. Reserved, NVS, bad-memory, device, and unknown types must remain unavailable under this teaching policy. ACPI reclaimable memory has a later reclamation phase. If two entries disagree, choose a conservative overlap policy in the normalizer. BIOS extended-attribute definitions have changed across ACPI revisions; preserve them and apply the revision contract you implement. Current ACPI specifies bit 0 as reserved and set to one, with additional error-log information in bit 3.',
        'A20 is another independent prerequisite. In the relevant early x86 environment, an inactive A20 gate can cause addresses above 1 MiB to alias lower addresses. Test the behavior with preserved scratch bytes before relying on high memory. A20 enabling does not discover RAM or configure page translation. Keep its verification separate from the E820 map.'),
      exercise('Find the three protocol bugs', 'A loader initializes EAX once, increments EBX after each result, and writes descriptors until EBX is zero into a 16-record buffer.', ['Explain the risk in each of those three choices.', 'Give a safe outcome when the 17th descriptor is needed.'], ['BIOS output can overwrite EAX, so each request must restore the function number.', 'EBX is a BIOS-owned continuation token, so incrementing it can skip records or invalidate the enumeration.', 'The loop needs a capacity check before the write. A full map can be rejected with a diagnostic, or a larger reserved buffer can be used according to the boot contract. Truncation must never make omitted ranges appear free.'], ['No out-of-bounds descriptor writes.', 'A failed or incomplete map cannot release unknown frames.'])
    ], [acpi]),
    topic('memory-normalize-ranges', 'normalize', 'Normalize ranges and reserve partial frames safely', [
      'The normalizer turns messy byte intervals into a set of complete, exclusively owned frames. Its two alignment rules point in opposite directions: usable intervals round inward, while occupied intervals round outward. A single occupied byte makes its entire physical frame unavailable.',
      'A robust implementation first validates endpoints, clips to its managed physical window, resolves overlaps, subtracts reservations, and only then exposes complete frames. The following arithmetic exercises that contract without requiring a BIOS or a page allocator.'
    ], [
      code('Complete frames inside a validated 64-bit byte interval', 'c', '#include <stdint.h>\n#include <stdbool.h>\n\nbool usable_frames(uint64_t base, uint64_t length,\n                   uint64_t cap, uint64_t *first,\n                   uint64_t *end) {\n    if (length == 0 || base > UINT64_MAX - length)\n        return false;\n    uint64_t hi = base + length;\n    if (base >= cap) return false;\n    if (hi > cap) hi = cap;\n    uint64_t lo_pfn = (base >> 12) + ((base & 4095) != 0);\n    uint64_t hi_pfn = hi >> 12;\n    if (lo_pfn >= hi_pfn) return false;\n    *first = lo_pfn;\n    *end = hi_pfn;\n    return true;\n}', [
        'The caller supplies non-null writable output pointers. On failure both outputs retain their old values. cap is an exclusive physical-address bound, such as 1ULL << 32.',
        'The subtraction check proves base + length cannot wrap. Checking after the addition would already have lost the true endpoint.',
        'The lower PFN is ceiling(base / 4096). Computing it from quotient and remainder avoids overflowing base + 4095.',
        'The upper PFN is floor(hi / 4096). Frames with indices first through end - 1 are complete inside the interval. This helper does not resolve descriptor overlap or reservations.'
      ]),
      trace('Inward and outward rounding', ['Input', 'Calculation', 'Result'], [
        ['Usable [0x1003,0x5000)', 'ceil(0x1003/4096)=2; floor(0x5000/4096)=5', 'Candidate PFNs {2,3,4}'],
        ['Reserved [0x2FF0,0x3010)', 'floor(start/4096)=2; ceil(end/4096)=4', 'Remove PFNs {2,3}'],
        ['Subtract reservation', '{2,3,4} minus {2,3}', 'Only PFN 4 can be released'],
        ['Usable [0xFFFFF000,0x100002000), cap=2^32', 'Clip end to 0x100000000', 'Only PFN 0xFFFFF is in the managed window']
      ]),
      p('For overlapping firmware entries, collect all endpoints, sort them, and inspect each interval between consecutive endpoints. An interval is allocatable only if usable coverage exists and no forbidden coverage exists. Merge adjacent intervals with the same final status. With `n` descriptors, sorting costs `O(n log n)`; an event sweep can update active type counts at each endpoint. A simpler bounded boot implementation can scan all descriptors for every interval at `O(n²)` and still be practical for a small, strictly limited map.',
        'Reservations must include the physical footprint of every loader module, the kernel including zero-filled BSS, stacks, boot records, page tables, framebuffer/device windows, and allocator metadata. A kernel linked at a high virtual address still needs its physical load interval reserved. Reserving only file bytes misses BSS. Reserving only fully covered pages misses boundary bytes.',
        'Normalize once into a canonical map and pass the result through a versioned boot-information structure. Include element size, element count, total buffer length, and address width. The kernel should verify count multiplied by element size without overflow before reading the array. This makes the handoff independently testable.'),
      exercise('Build a tiny canonical map', 'Usable intervals are [0x1000,0x9000) and [0x7000,0xB000). A forbidden interval is [0x5800,0x7800). The kernel owns [0x1800,0x2800).', ['List every free PFN after conservative normalization.', 'Count usable bytes represented by those free frames.', 'Explain whether overlapping usable entries double the count.'], ['The union of usable intervals covers PFNs 1 through 10. The forbidden interval removes PFNs 5,6,7. The kernel interval removes PFNs 1,2. Free PFNs are 3,4,8,9,10.', 'Five frames represent 5 × 4096 = 20,480 bytes.', 'Union coverage is a set of addresses. Duplicate usable coverage does not create additional physical frames.'], ['Free set = {3,4,8,9,10}.', 'Byte count = 20480.'])
    ], [acpi, kernelMemory])
  ],
  'physical-memory': [
    topic('pmm-bitmap-accounting', 'initialization', 'Implement a bitmap with an explicit frame state model', [
      'A physical allocator answers an ownership question: which complete frame may the caller use until it releases ownership? A bitmap stores one availability bit per frame. It is compact and easy to audit, but a single bit cannot distinguish reserved memory from an outstanding allocation.',
      'For `N` managed frames, the availability bitmap needs `ceil(N / 8)` bytes. Managing the full 4 GiB physical window with 4 KiB frames requires 1,048,576 bits, or 131,072 bytes. Those 32 metadata frames must themselves stay reserved.'
    ], [
      table('Separate availability from legal state transitions', ['State', 'Availability bit', 'Allowed transition'], [['Unavailable hole/reservation','1','Only an explicit boot or lifetime policy can make it allocatable.'],['Free RAM','0','Allocation atomically changes it to allocated.'],['Allocated RAM','1','Its owner may release it after references are retired.'],['Shared RAM','1','A reference count controls final release; one unmap is insufficient.']]),
      code('Bounded bitmap allocation and release model', 'c', '#include <stdint.h>\n#include <stdbool.h>\n#define NFRAME 64u\nstatic uint32_t busy[2] = { UINT32_MAX, UINT32_MAX };\nstatic uint32_t permitted[2];\nstatic uint32_t allocated[2];\n\nbool pmm_take(uint32_t *out) {\n    for (uint32_t f = 0; f < NFRAME; ++f) {\n        uint32_t w = f >> 5, m = 1u << (f & 31u);\n        if ((busy[w] & m) == 0) {\n            busy[w] |= m;\n            allocated[w] |= m;\n            *out = f;\n            return true;\n        }\n    }\n    return false;\n}\n\nbool pmm_release(uint32_t f) {\n    if (f >= NFRAME) return false;\n    uint32_t w = f >> 5, m = 1u << (f & 31u);\n    if (!(permitted[w] & m) || !(allocated[w] & m))\n        return false;\n    allocated[w] &= ~m;\n    busy[w] &= ~m;\n    return true;\n}', [
        'This is a uniprocessor model with all calls externally serialized. out must point to writable storage. Initial boot setup sets permitted bits and clears busy bits only for normalized free RAM. allocated starts zero.',
        'The bit index uses f & 31 so 1u is never shifted by 32 or more. The word index uses f >> 5.',
        'allocated rejects a release of reserved memory and a second release of the same frame. permitted retains the physical-RAM eligibility policy.',
        'Allocation costs O(NFRAME) in this simple scan; release costs O(1). A word scan with a find-first-zero operation reduces constants, and a next-search hint reduces repeated work near the beginning.'
      ]),
      p('Initialize every bit, including unused tail bits in the last word, to unavailable. Release known-good frames from the canonical map. Count free frames while applying transitions, and periodically compare the maintained counter with a bitmap recount in a diagnostic build. A mismatch often exposes a duplicate free or an incomplete rollback.',
        'The scan and the claim must form one synchronized operation. Two CPUs can both read the same zero bit before either stores a one. Protect the allocator with a lock, or use a correctly designed atomic test-and-set loop plus synchronized counters. On a single CPU, an interrupt can still reenter an allocator. Decide whether allocation is forbidden in interrupts or use an interrupt-safe locking protocol. Disabling interrupts on one CPU does not serialize other CPUs.',
        'Zeroing frames belongs to an ownership contract. A new userspace frame must not reveal a previous owner’s bytes. It can be cleared after it is exclusively allocated and before its user PTE is published. Clearing while it is still free allows another allocator to hand it out halfway through the operation.'),
      exercise('Test the allocator invariant', 'Frames 0 and 3 are permanently reserved in a 16-frame model. All other frames begin free.', ['Allocate until failure and count unique results.', 'Release frame 5 twice.', 'Attempt to release frame 0.', 'Describe the expected free-count changes.'], ['Exactly 14 distinct frames may be returned, with neither 0 nor 3 present.', 'The first release of allocated frame 5 succeeds and increments the count by one; the second fails and leaves the count unchanged.', 'Releasing frame 0 fails because it was never eligible or allocated.', 'After exhausting, freeing 5, and taking one frame again, the free count returns to zero.'], ['14 unique successful allocations.', 'Invalid releases preserve all state.'])
    ], [kernelMemory, ostep('18: Paging introduction', 'vm-paging')]),
    topic('pmm-free-stack-and-runs', 'unit', 'Choose a free stack, bitmap, or contiguous-run allocator', [
      'An array of free PFNs can implement allocation by pop and release by push. For independent single-frame requests, this gives constant-time operations. A bitmap gives compact address-indexed state and makes contiguous-run scans straightforward. The correct representation depends on the promises the interface makes.',
      'A page table can connect arbitrary physical frames into consecutive virtual pages. A device that requires a physically contiguous DMA buffer imposes a different constraint. Keep physical contiguity, virtual contiguity, alignment, and device reachability as separate allocation parameters.'
    ], [
      table('Representation costs for 1,048,576 frames', ['Representation', 'Metadata scale', 'Common operation'], [['One availability bitmap','128 KiB','Linear scan in worst case; indexed release.'],['Stack of 32-bit PFNs','4 MiB at full capacity','O(1) pop/push; separate ownership validation needed.'],['Intrusive linked free frames','A link stored inside each free frame','O(1) removal; links require accessible mappings.'],['Buddy free lists','Per-order lists plus frame metadata','O(log N) splitting or merging for power-of-two runs.']]),
      p('A free-stack implementation needs a capacity proof. If the stack holds `capacity` PFNs, every push must maintain `count <= capacity`. Checking only this condition does not reject a double free: the same PFN can appear twice while the array remains within bounds. Maintain allocation state independently, or require ownership discipline with strong diagnostics. Never store arbitrary user-controlled values in the stack.',
        'For a contiguous bitmap scan of `k` frames, maintain a run length. A busy bit resets the run to zero; a free bit increments it. When it reaches `k`, claim the interval while still holding the same lock. Starting PFNs may need alignment `a`, for example an eight-frame boundary. A candidate beginning at PFN 11 cannot satisfy `a = 8`, even if eight free frames follow it. Adjust to the next aligned PFN and restart the run check.',
        'An intrusive free list uses the first machine word of each free frame as its next link. That space is safe only while the frame is free. The allocator must read the next link before returning ownership. On release, it writes a link only after the previous owner has retired all uses. If physical memory lacks a permanent kernel mapping, every link access needs a temporary mapping, which changes the supposed constant-time operation’s practical cost.',
        'Single-frame availability does not predict contiguous success. Suppose PFNs 0 through 15 alternate allocated and free. Eight free frames exist, but the largest free run is one. A virtual arena of eight pages can still be assembled from those frames; a physically contiguous eight-page buffer fails. A compacting allocator can sometimes migrate movable contents, but pinned DMA pages and kernel objects impose limits.'),
      exercise('A constrained run search', 'In PFNs 0 through 15, free intervals are [1,7) and [8,14). A request needs four consecutive frames aligned to four frames.', ['Find all valid starts.', 'Give one reason a total-free-frame counter cannot answer the request.', 'Explain how the answer changes for an eight-frame request.'], ['The first interval has candidate aligned start 4, but [4,8) extends beyond its end 7. The second interval permits [8,12), so the only start is 8.', 'The counter says 12 frames are free but does not describe adjacency or alignment.', 'No eight-frame run exists, even though 12 frames are free.'], ['Four-frame result starts at PFN 8.', 'Eight-frame result is failure.'])
    ], [kernelMemory]),
    topic('pmm-buddy-split-coalesce', 'ownership', 'Derive the buddy allocator and trace every split', [
      'A buddy allocator manages aligned blocks containing `2^order` frames. Order 0 means one frame; order 3 means eight frames. A request for three pages rounds up to an order-2 block of four pages. That rounding makes merging cheap because each block has exactly one same-sized candidate partner.',
      'Within a power-of-two aligned arena, let `r` be the block’s starting PFN relative to the arena base. Its buddy begins at `r XOR (1 << order)`. Both partners share the same higher address bits and differ only in the bit selecting the lower or upper half of their parent.'
    ], [
      trace('Sixteen-frame arena at PFN 0; choose the lowest available address', ['Operation', 'Split or merge', 'Free lists afterward'], [
        ['Initial state','One order-4 block [0,16)','o4: {0}'],
        ['Allocate A: 3 pages','Round to o2. Split [0,16) into o3 at 0 and 8; split 0 into o2 at 0 and 4; give A [0,4).','o2: {4}; o3: {8}'],
        ['Allocate B: 1 page','Split o2 at 4 into o1 at 4 and 6; split 4 into o0 at 4 and 5; give B [4,5).','o0: {5}; o1: {6}; o3: {8}'],
        ['Allocate C: 2 pages','Take o1 at 6; give C [6,8).','o0: {5}; o3: {8}'],
        ['Free B at 4, o0','Buddy 4 XOR 1 = 5 is free; merge to o1 at 4. Buddy 4 XOR 2 = 6 is allocated.','o1: {4}; o3: {8}'],
        ['Free C at 6, o1','Buddy 6 XOR 2 = 4 is free; merge to o2 at 4. Buddy 4 XOR 4 = 0 belongs to A.','o2: {4}; o3: {8}'],
        ['Free A at 0, o2','Merge with 4 to o3 at 0, then with 8 to o4 at 0.','o4: {0}']
      ]),
      code('Buddy arithmetic using arena-relative frame numbers', 'c', '#include <stdint.h>\n#include <stdbool.h>\n\nbool buddy_of(uint32_t relative_pfn, unsigned order,\n              unsigned arena_order, uint32_t *out) {\n    if (arena_order >= 31 || order >= arena_order) return false;\n    uint32_t arena_pages = 1u << arena_order;\n    uint32_t block_pages = 1u << order;\n    if (relative_pfn >= arena_pages ||\n        (relative_pfn & (block_pages - 1u)) != 0) return false;\n    *out = relative_pfn ^ block_pages;\n    return true;\n}', [
        'This helper computes a candidate buddy only. out is writable; the arena base is aligned to its size, and relative PFNs are used throughout.',
        'The order checks keep shifts defined. An arena-sized block has no partner inside its own arena.',
        'A real free path must also prove the candidate is a free block head of the same order in the same arena and zone, then remove it from that free list before merging.',
        'The parent head is min(current, buddy). Increment order and repeat until no legal free partner remains.'
      ]),
      p('Store the allocation order with the block’s ownership record. If an order-2 allocation is accidentally freed as order 0, three pages disappear from accounting and later coalescing can overlap a live allocation. If a non-head page is freed, the alignment formula may produce a plausible number that still violates ownership. Validate block head, order, arena, and allocation state before editing lists.',
        'With a maximum arena order `m`, finding a suitable free list and splitting needs at most `m` order changes. Coalescing has the same bound. List insertion and removal must be constant time for the claimed `O(log N)` behavior; scanning a singly linked list for the buddy can add a larger cost. Metadata usually tells whether a buddy is a free head and where its list links live.',
        'Buddy allocation trades external fragmentation patterns for power-of-two internal waste. A five-page request consumes eight pages, leaving three pages unavailable to other callers until the entire block is freed. Adjacent free blocks cannot always merge: blocks at PFNs 4 and 8 are adjacent in some sizes but lack the required shared parent. A free-list visualization should show order boundaries so learners can distinguish adjacency from partnership.'),
      exercise('Why adjacency is insufficient', 'In a 16-frame arena, [4,8) and [8,12) are free order-2 blocks. Their neighbors [0,4) and [12,16) remain allocated.', ['Can the two free blocks form an order-3 allocation?', 'Compute each legal buddy.', 'Calculate internal waste for a five-page request satisfied from an order-3 block.'], ['They cannot merge because an order-3 block must start at a multiple of eight. The union [4,12) violates that alignment.', 'The buddy of 4 is 4 XOR 4 = 0. The buddy of 8 is 8 XOR 4 = 12.', 'Eight pages minus five requested pages leaves three pages, or 12,288 bytes, of internal waste.'], ['Buddy starts: 0 and 12.', 'Waste: 12288 bytes.'])
    ], [kernelMemory, ostep('17: Free-space management', 'vm-freespace')]),
    topic('pmm-zones-numa-pressure', 'concurrency', 'Add zones, locality, and pressure without losing ownership', [
      'A real frame request usually contains more information than a size. A device may address only a limited physical window. A CPU may access nearby NUMA-node memory with lower latency than remote memory. A caller holding a spinlock may be unable to sleep while reclaim runs.',
      'Represent these requirements explicitly: order, alignment, allowed physical interval, preferred node, fallback policy, and whether the allocation may block. A request that violates an essential device constraint must fail even when a different zone has free memory.'
    ], [
      table('Three independent axes', ['Axis', 'Question', 'Example consequence'], [['Zone or physical eligibility','Can this consumer address the frame?','A legacy device constrained below 16 MiB cannot use a frame at 64 MiB.'],['NUMA node','Where is this RAM relative to the CPU or device?','Prefer local memory; allow remote fallback only if policy permits.'],['Allocation context','May the caller sleep, reclaim, or perform I/O?','An interrupt handler needs an immediately available object or a reserved pool.']]),
      p('Do not merge buddy blocks across a hole, zone boundary, node boundary, or arena boundary. The XOR identity is meaningful only inside the allocator’s defined arena. A reserved interval can break a large contiguous range into several aligned blocks at initialization. Starting from all-unavailable state and adding normalized free runs preserves these boundaries.',
        'Per-CPU caches can reduce lock traffic for order-0 frames. A CPU first pops a local cached frame; an empty cache refills a batch from the shared allocator. The global free count must account for cached frames consistently. A machine can appear to lack contiguous memory while many isolated pages sit in CPU caches, so pressure handling may drain them before larger-order allocation attempts.',
        'Reclaim and compaction solve different problems. Reclaim recovers frames by dropping clean reconstructible contents or writing eligible dirty contents to backing storage. Compaction migrates movable contents to assemble larger free runs. Neither can freely move pinned DMA buffers, active page tables without a suitable protocol, or objects with untracked physical pointers. A teaching PMM can initially return a clear allocation failure and add these policies only when frame ownership is already reliable.',
        'Reserve some memory for the mechanism that makes progress under pressure. A page-fault handler that needs memory to read a swapped page can deadlock if its block-I/O request allocator also needs a free page from an empty pool. Bounded emergency pools, preallocated metadata, and carefully ordered reclaim paths are solutions to specific dependency cycles. Trace who calls whom before introducing an emergency reserve.'),
      exercise('Route three requests', 'Node 0 has two free pages below 16 MiB and 100 free pages above 4 GiB. Node 1 has 50 free pages below 4 GiB. This course kernel currently manages only physical addresses below 4 GiB.', ['Route a one-page legacy DMA request below 16 MiB.', 'Route a local-preferred ordinary page request when low memory on node 0 is reserved for DMA.', 'Explain why the 100 high pages do not help the present kernel.'], ['Use an eligible low page on node 0, subject to the DMA allocation policy.', 'A fallback-capable request can use node 1. Strict node-local policy would fail.', 'The current non-PAE physical mapping contract excludes those frames. Reporting their presence is different from being able to allocate and access them.'], ['Essential address constraints remain enforced during fallback.'])
    ], [kernelMemory])
  ],
  'virtual-memory': [],
  'kernel-heap': [],
  'user-mode': [],
  'elf-loader': []
};

memoryHandbook['virtual-memory'].push(
  topic('vm-base-bounds-segments', 'walk', 'Derive paging from relocation and segmentation', [
    'An address space is the set of virtual addresses a process may use together with the meaning and permissions of each region. Two processes can use the same virtual number for different objects because translation depends on the active address-space context. The kernel controls that context.',
    'Begin with a simple relocation machine: a process generates an offset `v`; hardware checks `v < limit` and computes physical address `base + v`. This model gives isolation if only privileged code can change base and limit and all accesses pass through the check.'
  ], [
    trace('A relocation machine with base 0x8000 and limit 0x3000', ['Virtual offset', 'Bounds check', 'Physical result'], [['0x0120','0x0120 < 0x3000','0x8120'],['0x2FFF','0x2FFF < 0x3000','0xAFFF'],['0x3000','Equal to exclusive limit','Fault; no physical access']]),
    p('One base-and-bounds pair requires a contiguous physical allocation for the whole process. A mostly empty address space still reserves the gap between its heap and stack. Segmentation introduces separate base, length, and permission records for logical regions such as code, data, and stack. Each segment can grow or be shared independently, but each still needs a suitable contiguous physical region in the simple model.',
      'Paging divides virtual addresses into equal-size pages and physical RAM into equal-size frames. A translation table can map consecutive virtual pages to scattered frames. With 4 KiB pages, the low 12 address bits identify a byte within the page; translation replaces the upper virtual-page number with a frame number while preserving those low bits. The kernel can leave unused virtual pages absent without reserving physical data frames for the gaps.',
      'This changes fragmentation. A paged process no longer requires one contiguous physical run for all of its ordinary pages. Its final partially used page still consumes a whole frame, and page tables consume additional frames. Larger physical requests, huge pages, and devices can still encounter external fragmentation. Say exactly which allocator and allocation unit a fragmentation claim refers to.',
      'On 32-bit x86, segmentation produces a linear address before paging translates it. This course usually gives code and data segments base zero with a 4 GiB span, so C virtual addresses coincide with linear addresses. The GDT still carries privilege and execution metadata. Flat segmentation does not remove the segmentation stage; it makes its base addition numerically invisible for these segments.'),
    table('Compare the promises', ['Mechanism','Physical placement','Protection granularity','Main cost'], [['One base and bound','One contiguous process region','Whole process range','Unused gaps and relocation constraints'],['Multiple segments','Contiguous region per segment','Logical segment','Variable-sized allocation and growth'],['Paging','Independent frame per ordinary page','Page, plus page-table hierarchy','Translation metadata, TLB misses, partial-page waste']]),
    exercise('Map a sparse process', 'A process uses 6 KiB of code at virtual 0, 5 KiB of data at 0x100000, and a 4 KiB stack at 0xBFFFF000. Use 4 KiB pages.', ['Count required data frames with separate mappings.', 'Calculate unused bytes inside the final code and data pages.', 'Explain why the virtual gaps need no data frames.'], ['Code needs two frames, data needs two, and stack needs one: five data frames before page-table overhead.', 'Code wastes 2 KiB and data wastes 3 KiB, totaling 5 KiB.', 'Absent entries represent the holes. A hierarchical structure may still need metadata for the portions containing live mappings.'], ['Five data frames.', '5120 bytes of partial-page waste.'])
  ], [ostep('15: Address translation', 'vm-mechanism'), ostep('16: Segmentation', 'vm-segmentation'), osc]),
  topic('vm-walk-10-10-12', 'walk', 'Walk a 32-bit address with actual entry addresses', [
    'Fix the hardware model before doing arithmetic: 32-bit protected mode, CR0.PG = 1, CR4.PAE = 0, ordinary 4 KiB pages, and present directory entries with PS = 0. Every directory and page table occupies one aligned 4096-byte physical frame containing 1024 entries of four bytes each.',
    'A 32-bit linear address splits into 10 directory-index bits, 10 table-index bits, and 12 offset bits. Derive the split: 4096 bytes need 12 offset bits; 4096 / 4 = 1024 entries need 10 index bits; the remaining 10 bits select a directory entry.'
  ], [
    { type:'bits', caption:'32-bit linear address for 4 KiB pages', width:32, fields:[{name:'Directory index',high:31,low:22,description:'Selects one of 1024 PDEs.'},{name:'Table index',high:21,low:12,description:'Selects one of 1024 PTEs.'},{name:'Byte offset',high:11,low:0,description:'Preserved when translating to physical memory.'}], value:'0x0040307A' },
    trace('CR3 = 0x00100000, linear address = 0x0040307A', ['Stage','Arithmetic','Result'], [['Directory index','v >> 22','1'],['Table index','(v >> 12) & 0x3FF','3'],['Offset','v & 0xFFF','0x07A'],['PDE physical address','(CR3 & 0xFFFFF000) + 4 × 1','0x00100004'],['Read PDE','Memory[0x00100004]','0x00102003'],['PTE physical address','(PDE & 0xFFFFF000) + 4 × 3','0x0010200C'],['Read PTE','Memory[0x0010200C]','0x00345067'],['Final physical address','(PTE & 0xFFFFF000) | 0x07A','0x0034507A']]),
    code('Pure arithmetic translation model with explicit permission checks', 'c', '#include <stdint.h>\n#include <stdbool.h>\n\nbool translate_4k(uint32_t v, uint32_t pde, uint32_t pte,\n                  bool user, bool write, bool cr0_wp,\n                  uint32_t *physical) {\n    if (!(pde & 1u) || !(pte & 1u)) return false;\n    if (pde & 0x80u) return false; /* PS=1 unsupported here */\n    if (user && (!(pde & 4u) || !(pte & 4u))) return false;\n    if (write && (user || cr0_wp) &&\n        (!(pde & 2u) || !(pte & 2u))) return false;\n    *physical = (pte & 0xFFFFF000u) | (v & 0xFFFu);\n    return true;\n}', [
      'This executable helper models address arithmetic and selected permissions. The caller provides entry values already fetched from the correct indices and a writable output pointer. Failure leaves the output untouched.',
      'The model excludes PAE, NX, large pages, SMEP, SMAP, protection keys, reserved-bit checks, and all physical memory dereferences. Its boolean result means permitted under these stated assumptions.',
      'Presence is required at both levels. User permission and write permission cannot be granted by a leaf when the parent denies them.',
      'For supervisor writes, CR0.WP controls whether read-only page permissions are enforced in this basic model. A kernel that relies on write protection should set WP.'
    ]),
    p('The supplied PDE value `0x00102003` is supervisor-only because bit 2 is clear. The supplied PTE has USER set, but a ring-3 access still fails. A supervisor read translates to the calculated physical address. Changing the PDE to `0x00102007` permits a user access when the leaf and requested operation also allow it. Address calculation and access authorization are related checks with different outputs.',
      'The page walker reads page-table structures through physical addresses. Kernel software editing them needs virtual mappings to those physical frames. After identity mapping disappears, dereferencing the raw PDE frame address as a C pointer can fault or touch an unrelated mapping. Hide that conversion behind a deliberate mapping interface.'),
    exercise('Repeat the walk at a boundary', 'Let v = 0x007FFFFF, CR3 = 0x00100000, PDE[1] = 0x00200007, and PTE[1023] = 0x009AB007.', ['Find both indices, offset, PTE physical address, and final physical address.', 'Explain what changes when v advances to 0x00800000.'], ['Directory index is 1, table index is 1023, and offset is 4095. The PTE sits at 0x00200FFC; the final address is 0x009ABFFF.', 'The directory index becomes 2, table index becomes 0, and offset becomes 0. A different PDE now selects the table.'], ['PTE address = 0x00200FFC.', 'Physical address = 0x009ABFFF.'])
  ], [intel, ostep('18: Paging introduction', 'vm-paging')]),
  topic('vm-page-entry-bits', 'permissions', 'Read every field in a legacy PDE and PTE', [
    'An entry combines an aligned physical base with control bits. Alignment supplies the otherwise-zero low bits, making room for metadata. The meaning of a bit depends on the level and page size. In particular, bit 7 means page size in a PDE and PAT selection in a 4 KiB PTE.',
    'These diagrams describe present entries in 32-bit non-PAE paging. Optional PAT and global-page behavior require CPU support and appropriate controls. Keep unsupported and reserved bits clear. Nonpresent entries may carry software information under an explicitly defined kernel format.'
  ], [
    { type:'bits', caption:'Present PDE pointing to a 4 KiB page table, PS = 0', width:32, fields:[
      {name:'Table physical base',high:31,low:12,description:'Aligned page-table frame address.'},{name:'Software',high:11,low:9,description:'Available to software in this format.'},{name:'Ignored',high:8,low:8,description:'Not a global leaf mapping here.'},{name:'PS = 0',high:7,low:7,description:'Selects a page-table pointer.'},{name:'Ignored',high:6,low:6,description:'No leaf dirty bit in this PDE format.'},{name:'A',high:5,low:5,description:'Accessed during translation.'},{name:'PCD',high:4,low:4,description:'Page-table access cache control.'},{name:'PWT',high:3,low:3,description:'Page-table access write-through control.'},{name:'U/S',high:2,low:2,description:'Allows user access only if the leaf also permits it.'},{name:'R/W',high:1,low:1,description:'Upper-level write permission.'},{name:'P',high:0,low:0,description:'Present entry.'}
    ] },
    { type:'bits', caption:'Present PTE mapping a 4 KiB data frame', width:32, fields:[
      {name:'Frame physical base',high:31,low:12,description:'Aligned physical frame address.'},{name:'Software',high:11,low:9,description:'Kernel bookkeeping, such as a COW marker.'},{name:'G',high:8,low:8,description:'Global translation when CR4.PGE enables it.'},{name:'PAT',high:7,low:7,description:'With PCD and PWT selects a PAT entry on supporting CPUs.'},{name:'D',high:6,low:6,description:'Set for writes to this leaf mapping.'},{name:'A',high:5,low:5,description:'Set when the mapping is accessed.'},{name:'PCD',high:4,low:4,description:'Part of leaf memory-type selection.'},{name:'PWT',high:3,low:3,description:'Part of leaf memory-type selection.'},{name:'U/S',high:2,low:2,description:'Leaf user permission.'},{name:'R/W',high:1,low:1,description:'Leaf write permission.'},{name:'P',high:0,low:0,description:'Frame is present.'}
    ] },
    { type:'bits', caption:'Present 4 MiB PDE, restricted to physical addresses below 4 GiB', width:32, fields:[
      {name:'4 MiB physical base',high:31,low:22,description:'Top ten physical-address bits; base is 4 MiB aligned.'},{name:'Keep zero in this model',high:21,low:13,description:'Reserved and capability-dependent address-extension positions. This example excludes PSE-36 addresses.'},{name:'PAT',high:12,low:12,description:'Leaf PAT selector when supported; differs from the 4 KiB PTE position.'},{name:'Software',high:11,low:9,description:'Kernel-defined bookkeeping.'},{name:'G',high:8,low:8,description:'Global leaf mapping when CR4.PGE enables it.'},{name:'PS = 1',high:7,low:7,description:'Large leaf with CR4.PSE and required CPU support.'},{name:'D',high:6,low:6,description:'Dirty state for the large mapping.'},{name:'A',high:5,low:5,description:'Accessed state for the large mapping.'},{name:'PCD',high:4,low:4,description:'Leaf memory-type selection.'},{name:'PWT',high:3,low:3,description:'Leaf memory-type selection.'},{name:'U/S',high:2,low:2,description:'User access permission.'},{name:'R/W',high:1,low:1,description:'Write permission.'},{name:'P',high:0,low:0,description:'Present leaf.'}
    ] },
    table('Interpret fields by function', ['Fields','How software uses them','Common mistake'], [['P','Publish a complete mapping only after its backing memory and metadata are ready.','Setting P before clearing a new table exposes garbage entries.'],['U/S and R/W','Combine permissions across the walk and consider CPL and CR0.WP.','Checking only the PTE.'],['A and D','Sample activity and dirty state, while coordinating with concurrent hardware updates.','Clearing A without the necessary invalidation and assuming the next access must update it.'],['PWT, PCD, PAT','Choose memory types using the architecture rules and device requirements.','Treating PCD as a universal substitute for correct MMIO memory typing.'],['G','Retain selected mappings across ordinary context changes when enabled.','Assuming a CR3 reload always removes global translations.'],['Software bits','Store meanings documented by the kernel, such as ownership or COW.','Confusing a software tag with a hardware permission.']]),
    p('Legacy non-PAE entries have no NX bit. A read-only user page can still be executable. The loader can record intended execute permissions, but this paging mode cannot enforce all modern W^X policies at page granularity. NX becomes available in suitable PAE or long-mode configurations when the processor supports it and EFER.NXE is enabled.',
      'A 4 MiB mapping sets PDE.PS and uses CR4.PSE with the required CPU support. Translation uses a 22-bit page offset and a 4 MiB physical base. Its PDE is a leaf: accessed, dirty, global, and leaf cache controls now apply there, and PAT occupies bit 12 when supported. Address-extension fields under PSE-36 depend on supported physical-address width; a simple below-4-GiB kernel keeps those fields zero and verifies reserved bits.',
      'For a supported below-4-GiB 4 MiB mapping, `physical = (pde & 0xFFC00000) | (v & 0x003FFFFF)`. One such leaf replaces a full table of 1024 ordinary mappings. It requires physical alignment and contiguity, and all subpages share the leaf permissions. Splitting it into 4 KiB mappings is necessary when one subpage needs independent permissions or ownership.'),
    exercise('Decode three entries', 'Use the stated non-PAE model. PTE A is 0x00123067, PTE B is 0x00123005, and PDE C is 0x00800083.', ['List P, R/W, U/S, A, and D for A.', 'Determine whether a user write through B is allowed when its PDE is user-writable.', 'Describe C assuming PSE support and CR4.PSE = 1.'], ['A has present, writable, user, accessed, and dirty bits set.', 'B is present and user-accessible but read-only; a user write faults.', 'C is a present writable supervisor 4 MiB mapping whose physical base is 0x00800000. It does not point to a page table.'], ['A flags = P|RW|US|A|D.', 'B user write faults.', 'C uses a 22-bit offset.'])
  ], [intel]),
  topic('vm-bootstrap-highhalf-recursive', 'bootstrap', 'Keep execution alive while enabling paging', [
    'Turning on paging changes the interpretation of every subsequent instruction fetch, stack access, and data access. The enabling code must already have a mapping for its current linear instruction address and stack. The page directory itself is selected by its physical address in CR3.',
    'For the first transition, build a small identity map covering the active code, stack, descriptor tables, boot records, and page-table editing needs. If the kernel will execute at a high virtual address, establish that alias before enabling paging and make the control-flow transition explicit.'
  ], [
    steps('A controlled 32-bit paging transition', [['Reserve and clear','Allocate aligned directory/table frames and keep them out of the PMM free pool. Zero tables through addresses usable before paging.'],['Construct both views','Map the current low execution region and the intended high kernel range to the correct physical frames. Set supervisor permissions; preserve device memory-type requirements.'],['Load the physical root','Write CR3 with the physical directory base and applicable low control bits. Configure only supported CR4 features.'],['Enable and transfer','Set CR0.PG with the intended CR0.WP policy. Continue through mapped instructions, then branch to the linked high virtual entry and establish its mapped stack.'],['Retire temporary mappings','Remove low aliases only after instruction, stack, descriptor, and boot-information references have moved. Invalidate their translations before reusing affected frames.']]),
    p('A high-half layout is a convention chosen by the OS. For example, mapping virtual `0xC0000000 + physical` for a bounded physical window gives a simple direct mapping. That addition is valid only inside the defined window; it is not a universal physical-to-pointer conversion. The virtual range also consumes part of the 4 GiB address space and may overlap other kernel mappings if the window grows without a plan.',
      'A recursive mapping makes the directory point to itself in one entry. With recursive slot 1023, set PDE[1023] to the physical directory address with supervisor permissions. Virtual addresses in `[0xFFC00000, 0x100000000)` then expose the page-table hierarchy. The directory appears at `0xFFFFF000`; the table selected by directory index d appears at `0xFFC00000 + d × 4096`. These formulas follow from running the same 10/10/12 walk twice.',
      'For virtual address v, the PTE can be reached at `0xFFC00000 + (v >> 12) × 4` when the corresponding directory entry points to an ordinary present table. If that table is absent, reading this recursive address faults. The PDE for v is at `0xFFFFF000 + (v >> 22) × 4`. Large-page PDEs need special handling because the recursive interpretation no longer describes an ordinary table.',
      'Recursive mappings expose writable translation metadata, so keep them supervisor-only at every relevant level. They consume one directory slot, equal to 4 MiB of virtual address space in this mode. They make editing convenient but do not supply ownership locks, protect against concurrent walkers, or remove the need for TLB invalidation.'),
    exercise('Derive the recursive addresses', 'PDE[1023] points to the current directory. Find the PDE and PTE virtual addresses for v = 0x0040307A.', ['Apply both formulas.', 'Explain why an absent PDE[1] prevents reading the PTE address.', 'Name a structure that must stay mapped while a page-fault handler runs.'], ['PDE address = 0xFFFFF000 + 4 = 0xFFFFF004. PTE address = 0xFFC00000 + 0x403 × 4 = 0xFFC0100C.', 'The recursive virtual page selects directory entry 1 as the table-to-read; when that entry is absent, the recursive access itself cannot translate.', 'The handler code, its stack, the IDT, and any data it requires must be reachable; losing the exception stack can cascade into a double fault.'], ['PDE = 0xFFFFF004; PTE = 0xFFC0100C.'])
  ], [intel]),
  topic('vm-pae-four-level-sizing', 'walk', 'Scale the table design to PAE and four levels', [
    'The 10/10/12 split follows from the selected entry width and address width. It is not a universal property of x86. Wider entries allow more physical-address bits and new controls, while consuming more bytes in each table. Re-derive the index sizes whenever the mode changes.',
    'A flat table for every 4 KiB page in a 32-bit space needs 2^20 entries. With four-byte entries, that is 4 MiB per address space, even when only a few pages are used. Hierarchical tables allocate lower levels only beneath populated portions of the virtual space.'
  ], [
    table('Three modes with ordinary 4 KiB leaf pages', ['Mode','Address partition','Entry size','Large leaf options'], [['32-bit non-PAE','10 directory + 10 table + 12 offset','4 bytes','4 MiB PDE with PSE'],['32-bit PAE','2 root + 9 directory + 9 table + 12 offset','8 bytes','2 MiB PDE'],['64-bit, four-level translation','9 PML4 + 9 PDPT + 9 PD + 9 PT + 12 offset','8 bytes','2 MiB PDE; 1 GiB PDPTE where supported']]),
    p('For the four-level example, assume 48-bit canonical virtual addresses and no fifth level. Bits 63 through 48 repeat bit 47. Canonicality is an architectural address-validity condition; the unused upper bits are not additional page-table indices. CPUs and operating systems can also support five-level paging and wider canonical addresses, so a four-level mask must not silently be reused there.',
      'PAE widens entry formats while the program still generates a 32-bit linear address. The root has four entries; each selects a directory with 512 entries. Each directory entry covers 2 MiB with ordinary lower-level tables, and a leaf table maps 512 × 4 KiB = 2 MiB. Physical-address width is a CPU capability and must be queried; an eight-byte entry does not promise that all 64 bits can hold a physical address.',
      'Count metadata by counting distinct paths. In the non-PAE mode, one mapped page needs one directory and one table: 8 KiB of metadata. Two pages in the same 4 MiB virtual region share the table. Two pages in different regions require two tables plus the directory: 12 KiB. Fully mapping all 4 GiB with ordinary leaves uses 1024 tables plus one directory, or 4 MiB + 4 KiB.',
      'In four-level paging, one isolated leaf normally needs a root, a PDPT, a PD, and a PT: 16 KiB of metadata for a new otherwise-empty address space. Two pages share upper levels according to their common indices. A large leaf stops the walk early and saves lower-level tables, but increases alignment, contiguity, and permission-granularity requirements. Actual memory access cost also depends on TLBs and page-walk caches; depth alone does not determine every access latency.'),
    trace('Count non-PAE metadata frames by distinct directory indices', ['Mapped virtual pages','Directory indices used','Metadata total'], [['0x00000000 only','{0}','1 directory + 1 table = 8 KiB'],['Add 0x003FF000','{0}','Still 8 KiB'],['Add 0x00400000','{0,1}','1 directory + 2 tables = 12 KiB'],['Add 0xBFFFF000','{0,1,767}','1 directory + 3 tables = 16 KiB']]),
    exercise('Sparse versus dense overhead', 'A non-PAE process has one mapped page in each of 32 different directory regions.', ['Count data frames and metadata frames.', 'Compare with 32 adjacent mapped pages contained in one directory region.', 'Explain one reason a huge page is unsuitable for the sparse layout.'], ['There are 32 data frames and 33 metadata frames: one directory plus 32 tables.', 'The dense arrangement still has 32 data frames, but only two metadata frames.', 'Each huge page would reserve a large physically contiguous region and a coarse permission unit to serve one small occupied page.'], ['Sparse metadata = 135168 bytes.', 'Dense metadata = 8192 bytes.'])
  ], [intel, kernelTables, ostep('20: Advanced page tables', 'vm-smalltables')]),
  topic('vm-tlb-shootdown', 'tlb', 'Treat translations as cached permissions with a lifetime', [
    'A TLB caches a translation and associated access information. A hit avoids walking the in-memory table for that address. Editing a PTE changes the source of truth in RAM, but another access can still use a cached translation until the architecture’s invalidation rules are satisfied.',
    'This matters most when revoking access or recycling a frame. If virtual page A formerly mapped frame F and the kernel frees F before removing every old translation, an old access through A can corrupt F after it has been assigned to a different owner.'
  ], [
    trace('The stale-translation failure', ['Time','CPU 0','CPU 1'], [['1','PTE[A] points to frame F.','Caches A → F in its TLB.'],['2','Clears PTE[A].','Has not yet observed an invalidation.'],['3','Incorrectly releases F; allocator gives it to B.','Still caches A → F.'],['4','B writes its new object into F.','A stale store through A overwrites B’s object.']]),
    steps('A safe revocation protocol', [['Serialize mapping state','Acquire the address-space synchronization needed to prevent conflicting mappings and walkers. Record which CPUs might use this address space.'],['Publish the change','Clear or restrict the mapping using the architecture’s required page-table update rules and ordering.'],['Invalidate participating CPUs','Invalidate locally and request invalidation on every relevant remote CPU. Each target performs the required operation for its current context.'],['Wait for completion','Wait for acknowledgments or use a proven deferred-reclamation mechanism. Account for CPUs entering or leaving the address space during the operation.'],['Release ownership','Only after stale access is impossible and software references are retired may the backing frame or page-table frame return to the PMM.']]),
    p('For the basic legacy x86 mode, INVLPG is a privileged instruction that invalidates the translation associated with a linear address on the executing logical processor under architectural rules. Reloading CR3 is useful for broader invalidation, but global mappings have special behavior when CR4.PGE is enabled. Neither instruction automatically broadcasts to other processors. A compiler barrier alone cannot invalidate a TLB.',
      'Address-space identifiers let a TLB distinguish identical virtual page numbers belonging to different contexts. ASID is the generic term; x86 PCID is an architecture-specific feature with its own mode requirements and invalidation rules. The simple 32-bit non-PAE course kernel should not assume PCID is available. Reusing an identifier requires retiring stale entries from its previous owner before the new address space can inherit that tag.',
      'A TLB miss and a page fault are different events. A miss can be resolved by a successful hardware walk through present permitted entries, with no kernel exception. A page fault occurs when translation or access checks fail. A benchmark that touches one byte in each mapped page may generate many TLB misses while producing no demand-page faults after warmup.',
      'A simple latency model makes the value measurable. Suppose a TLB lookup takes 1 ns and a memory access takes 80 ns, with no caches or overlap. A hit costs 81 ns; a two-level miss costs 1 + 3 × 80 = 241 ns. At 99% hit rate, the average is 0.99 × 81 + 0.01 × 241 = 82.6 ns. This is a teaching model; real caches, parallelism, and page-walk caches change the numbers.'),
    exercise('Revoke a shared mapping', 'An address space has run on CPUs 0 and 2. CPU 0 removes a writable mapping and wants to immediately reuse the physical frame.', ['List the events that must precede reuse.', 'Explain why an acknowledgment sent before invalidation is wrong.', 'Decide whether CPU 1 needs an invalidation if it has never used the context and has no matching retained translations.'], ['Publish the removal, invalidate the relevant local and remote translation state, obtain completion, and retire software references before recycling the frame.', 'Early acknowledgment allows the freeing CPU to recycle a frame while the target can still access it through stale permissions.', 'A proven context-tracking protocol can avoid targeting CPU 1. The proof must include tagged or retained translations and concurrent context switches.'], ['Reuse requires completed invalidation on every relevant CPU.'])
  ], [intel, kernelTlb, ostep('19: Translation lookaside buffers', 'vm-tlbs')]),
  topic('vm-map-unmap-transactions', 'bootstrap', 'Map pages with rollback and unmap with deferred reuse', [
    'A mapping operation can allocate more than one resource: a data frame, a page-table frame, and bookkeeping records. Failure halfway through must restore ownership without erasing a mapping that existed before the call. Define the operation’s contract before writing the first PTE store.',
    'For this model, `map_new(v, frame, flags)` requires a page-aligned virtual address, an owned page-aligned physical frame, legal flags, and an unmapped destination. It borrows the supplied data frame until success; on success the address space takes the agreed reference. An already-present destination returns an error.'
  ], [
    code('Transactional structure, intentionally pseudocode', 'text', 'map_new(space, v, owned_frame, flags):\n    validate_alignment_range_and_flags()\n    lock(space)\n    reject_if_destination_already_present()\n    new_table = none\n    if directory_slot_is_absent():\n        new_table = allocate_table_frame()\n        if allocation_failed: unlock_and_fail()\n        zero_entire_table_through_kernel_mapping()\n    prepare_nonpresent_leaf_and_ownership_record()\n    if preparation_failed:\n        release_only_new_table_if_any()\n        unlock_and_fail()\n    publish_required_directory_entry_if_any()\n    publish_present_leaf_with_final_permissions()\n    perform_required_translation_synchronization()\n    unlock(space)\n    return success', [
      'This pseudocode defines the control-flow contract; a kernel implementation must supply the listed operations. Allocation and locking order need adjustment if the allocator can sleep; a production design may allocate outside the lock and revalidate after acquiring it.',
      'The table is zeroed before the directory publishes it. Otherwise random present bits can expose arbitrary physical frames.',
      'Rollback releases only resources created by this invocation. A preexisting table and other leaves remain owned by the address space.',
      'Directory user/write flags must permit the intended leaf, while every other leaf retains its own restrictions. Changing an existing parent permission can affect many translations and needs the corresponding synchronization.'
    ]),
    p('A useful implementation tracks every provisional resource in local variables. After each successful allocation, record ownership before the next operation that can fail. A single cleanup path then releases resources in reverse order. Once publication transfers ownership, clear the provisional variable so cleanup cannot free the same resource twice. This pattern also applies to ELF loading and fork.',
      'Unmapping is a revocation followed by a possible release. Clear the leaf under the address-space lock, remove software metadata, invalidate translations, and release the data-frame reference only after stale access is impossible. A shared or COW frame can remain allocated because other mappings still hold references. A physical frame number alone does not tell you whether the final reference has disappeared.',
      'When a table loses its last leaf, it may also be reclaimable. Keep a live-leaf count or inspect all entries under synchronization. Detach the parent pointer before freeing the table, then satisfy both hardware page-walk/TLB rules and software-walker lifetime rules. A page-table frame freed too early can be reused as ordinary data while a CPU still interprets its contents as translation entries.',
      'For an n-page request, specify whether partial completion is observable. An all-or-nothing API must either reserve all resources before publication or maintain a rollback log of exactly the new mappings. A partial API must return an exact progress count and leave ownership well defined for the remaining supplied frames. Hidden partial success makes callers leak or double-free memory.'),
    exercise('Inject a failure on page three', 'A request maps four new pages. The first two mappings succeed; the third needs a page-table frame and PMM allocation fails. The API promises all-or-nothing behavior.', ['List what rollback removes.', 'Name two resources that must remain untouched.', 'State when the first two data frames can be reused.'], ['Remove the two newly published leaves and their ownership records. Detach any newly created tables that become unused, then perform required translation synchronization.', 'Preexisting mappings in the same tables and preexisting table frames remain intact.', 'Reuse waits for translation invalidation and software-reference retirement, and must respect the API’s data-frame ownership contract.'], ['The address space matches its pre-call mapping state after failure.'])
  ], [intel, kernelTlb]),
  topic('vm-page-fault-decoding', 'faults', 'Decode CR2 and the page-fault error word', [
    'A page fault is exception vector 14. The CPU records the faulting linear address in CR2 and supplies an error code on the exception stack. The saved instruction pointer identifies the instruction whose access failed; CR2 identifies an address that access attempted. They need not be equal.',
    'Capture CR2 early because another page fault can overwrite it. The handler must already have a reliable mapped stack and accessible code. Its logging path should avoid arbitrary allocation or user pointers, because a diagnostic that faults recursively can destroy the evidence.'
  ], [
    { type:'bits', caption:'Page-fault error word for the basic 32-bit non-PAE course model', width:32, fields:[{name:'Outside basic model',high:31,low:4,description:'Treat as architectural extension/reserved space for this model. Modern CPUs define additional bits; decode according to enabled features.'},{name:'RSVD',high:3,low:3,description:'Reserved bit set in a paging structure used by the walk.'},{name:'U/S',high:2,low:2,description:'Access classified as user-mode versus supervisor-mode.'},{name:'W/R',high:1,low:1,description:'Write access versus read access.'},{name:'P',high:0,low:0,description:'0: not-present condition; 1: protection violation, including reserved-bit faults.'}] },
    table('Four basic examples', ['Error code','Decode','First investigation'], [['0x0','Supervisor read; not present','Missing kernel mapping, absent lazy page, or bad pointer'],['0x4','User read; not present','Does a valid user region authorize demand allocation or page-in?'],['0x7','User write; protection violation','Read-only mapping, parent permission, or a valid COW event'],['0xB','Supervisor write; reserved-bit violation','Corrupt or incorrectly formatted paging entry; inspect mode-specific reserved bits']]),
    p('The error word describes the failed access class. Software metadata establishes the underlying cause. A protection write fault might be intentional COW, a genuine write to immutable code, or an incorrect parent flag. Consult the address-space region metadata and software PTE tags. Do not resolve every user write fault by setting RW; that turns protection errors into permission escalation.',
      'In configurations supporting execute-disable, error bit 4 can identify an instruction-fetch fault under the architectural conditions. Later features also add protection-key, shadow-stack, SGX, and other distinctions. Decode only against the exact CPU mode and enabled features. This course’s non-PAE model has no page-level NX and should not pretend to provide execute-denial behavior it cannot express.',
      'A recoverable handler establishes the missing resource or permission, completes the required invalidation, restores the saved context, and returns so the faulting instruction can retry. The handler does not usually advance EIP past that instruction. Instructions with multiple memory effects and restart behavior are architecture-defined, so follow the CPU’s fault semantics when restoring execution.',
      'For an invalid user access, terminate or signal that process according to the kernel contract. For an unexpected kernel access, preserve a crash record including CR2, error code, EIP, CR3, privilege state, and relevant page-table entries. A controlled user-copy routine can provide a special recovery path for expected kernel faults while accessing user memory; arbitrary kernel faults must not be silently converted to success.'),
    exercise('Classify a write fault', 'CR2 = 0x00801FFE and error code = 0x7. The saved EIP is 0x00401020. The leaf is present, user, read-only, and marked COW; its frame has two references.', ['Explain why CR2 differs from EIP.', 'Describe a valid recovery.', 'Explain how the response changes if the COW marker is absent and the region is immutable.'], ['EIP points to the instruction; CR2 points to its data access.', 'Allocate and copy a private frame, revalidate the mapping, install the writable private leaf, invalidate stale translation state, and drop the old reference. Retry the instruction.', 'The write violates the region permissions and should produce the process-level fault outcome. It must not gain write access.'], ['0x7 means present/protection + write + user.'])
  ], [intel]),
  topic('vm-demand-cow-swap', 'faults', 'Use faults to implement demand paging, COW, and swap', [
    'Separate a virtual region’s logical validity from a particular PTE’s current presence. A region record can say that addresses belong to an anonymous writable allocation while some of its pages have no resident frame. The fault handler uses this higher-level record to decide whether it may supply a frame.',
    'This distinction supports lazy zero-filled pages, file-backed mappings, copy-on-write sharing, and swapped pages. Each mechanism needs a different backing-state record. A zero PTE by itself cannot tell the handler whether a page is valid, file-backed, swapped, or completely outside the process.'
  ], [
    table('Fault state and recovery resource', ['Software state','Typical hardware fault','Recovery'], [['Valid anonymous, never touched','Not present','Allocate a frame, zero it, publish appropriate permissions.'],['Valid file-backed, not resident','Not present','Read the correct file bytes, zero required tail bytes, then publish.'],['Private COW sharing','Write protection','Copy into a private frame or upgrade safely if exclusively owned.'],['Valid page stored in swap','Not present','Locate the swap slot, read the contents, restore resident metadata.'],['No valid region or forbidden access','Either class','Deliver a process error; no mapping is created.']]),
    trace('Fork with one COW page', ['Event','Parent mapping','Child mapping','Frame references'], [['Before fork','P → F, writable','No child','F: 1'],['Create child','P → F, read-only+COW','P → F, read-only+COW','F: 2'],['Retire old parent write permissions','Invalidate parent writable translations','Child may run after setup','F: 2'],['Child writes','P → F, read-only+COW','Fault allocates G and copies F','F: 2; G: provisional'],['Publish child private page','P → F, read-only+COW','P → G, writable','F: 1; G: 1'],['Parent later writes','May upgrade F after proving exclusive ownership','P → G, writable','F: 1; G: 1']]),
    p('The parent must lose writable cached translations when sharing begins. Clearing RW only in RAM leaves a window where the parent modifies a frame that the child expects to remain a shared snapshot. Frame reference counts, address-space locks, and TLB synchronization together establish the COW invariant. A reference count check is meaningful only under a protocol that prevents a new sharer from appearing concurrently.',
      'Page-in can block on storage, so do not hold a spinlock across the I/O. Mark the page as being filled under a suitable lock, let additional faults wait on the same operation, perform I/O into an exclusively owned frame, then revalidate that the region and backing identity still exist before publication. Another thread may have unmapped the region while the read was in progress. Losing that race requires cleanup while keeping the removed region absent.',
      'Eviction is the reverse lifetime problem. A clean file-backed page can often be discarded because the file remains its backing source. A dirty anonymous page needs a retained copy, commonly a swap slot, before its frame can be reused. Prevent writes or detect concurrent redirtying while writeback is in progress, update backing metadata, revoke mappings, invalidate translations, and release the frame only when the contents remain recoverable.',
      'The I/O cost dominates many faults. In a deliberately simplified model with 100 ns normal access and 2 ms additional major-fault service, a fault probability of one in 100,000 adds 20 ns to the average. The result is 120 ns, a 20% increase. A minor fault that merely allocates or maps resident memory has a different service cost. Report fault counts by cause when diagnosing a workload.'),
    exercise('Resolve a concurrent page-in', 'Thread A faults on a file page and starts reading. Thread B unmaps the region before the read finishes.', ['Explain what A must check before publishing its PTE.', 'State what happens to the completed data frame if the region is gone.', 'Explain why keeping the address-space lock held across arbitrary disk I/O is undesirable.'], ['A checks that the region, permissions, file identity, and page offset still correspond to the operation it started.', 'The provisional frame and I/O state are released; the removed region stays unmapped.', 'It can block unrelated mapping operations and may violate lock rules or cause dependency cycles. Sleeping requires a lock and lifetime design that permits it.'], ['A completed read never recreates a removed region accidentally.'])
  ], [ostep('21: Beyond physical memory, mechanisms', 'vm-beyondphys'), kernelTables])
);

memoryHandbook['virtual-memory'].push(
  topic('vm-fifo-lru-opt-trace', 'faults', 'Compute FIFO, LRU, and OPT decisions on the same stream', [
    'Replacement chooses a resident page to evict when a needed page lacks a free frame. A policy comparison is meaningful only when frame count, initial contents, reference sequence, and tie rules are identical. Count cold faults too, and show whether a hit changes policy state.',
    'Use three initially empty frames and the original reference stream `2,5,2,1,5,7,2,5,1,7,2,8,5`. FIFO evicts the oldest arrival; hits preserve queue order. LRU evicts the least recently referenced resident page; every hit updates recency. OPT evicts the page whose next reference is farthest away, treating no future reference as infinity.'
  ], [
    trace('H = hit; F = fault. FIFO lists oldest first. LRU and OPT show fixed frame slots.', ['Step/page','FIFO state','LRU state','OPT state'], [['1 / 2','F [2]','F [2]','F [2]'],['2 / 5','F [2,5]','F [2,5]','F [2,5]'],['3 / 2','H [2,5]','H [2,5]','H [2,5]'],['4 / 1','F [2,5,1]','F [2,5,1]','F [2,5,1]'],['5 / 5','H [2,5,1]','H [2,5,1]','H [2,5,1]'],['6 / 7','F [5,1,7]; evict 2','F [7,5,1]; evict 2','F [2,5,7]; evict 1'],['7 / 2','F [1,7,2]; evict 5','F [7,5,2]; evict 1','H [2,5,7]'],['8 / 5','F [7,2,5]; evict 1','H [7,5,2]','H [2,5,7]'],['9 / 1','F [2,5,1]; evict 7','F [1,5,2]; evict 7','F [2,1,7]; evict 5'],['10 / 7','F [5,1,7]; evict 2','F [1,5,7]; evict 2','H [2,1,7]'],['11 / 2','F [1,7,2]; evict 5','F [1,2,7]; evict 5','H [2,1,7]'],['12 / 8','F [7,2,8]; evict 1','F [8,2,7]; evict 1','F [8,1,7]; evict slot 0'],['13 / 5','F [2,8,5]; evict 7','F [8,2,5]; evict 7','F [5,1,7]; evict slot 0'],['Total','11 faults; 2 hits','10 faults; 3 hits','7 faults; 6 hits']]),
    p('At step 6, OPT keeps pages 2 and 5 because they return at steps 7 and 8, while page 1 returns at step 9. At step 9, page 5 returns at step 13, later than pages 7 and 2, so OPT evicts 5. At steps 12 and 13, several pages have no future use; this table breaks ties by the lowest frame slot. Other ties can produce different final contents with the same minimum fault count.',
      'OPT supplies a lower bound for this exact trace and capacity because it knows the future. A real general-purpose kernel cannot rely on future references being available. LRU uses recent history as a prediction. FIFO ignores that history after arrival, so a frequently used old page can still be its next victim. None of the three definitions incorporates dirty-writeback cost in this basic experiment.',
      'In a simulator, FIFO can use a queue with constant-time victim selection plus a membership structure. Exact LRU can use a hash table and linked recency list with expected constant-time operations, or timestamps and an O(F) victim scan. A real MMU does not trap on every memory reference so software can update a linked list. Hardware accessed bits support approximations with much lower observation overhead.',
      'For a simple OPT simulator with R references and F frames, scanning the future for every candidate gives a poor O(R²F) bound. Precompute future occurrence queues and compare their next positions at each eviction, reducing unnecessary rescans. Keep the policy mechanics separate from storage I/O to validate the page-choice algorithm first.'),
    exercise('Change the trace without guessing', 'Append page 5 once more to the displayed stream.', ['Predict the extra fault count for all three policies.', 'Explain which metadata changes on the new hit.', 'Then append page 7 and evaluate each policy from its final state.'], ['The extra 5 is a hit for all policies because each final state contains 5.', 'FIFO arrival order stays unchanged; LRU makes 5 most recent; OPT needs no replacement decision.', 'After the repeated 5, page 7 faults for FIFO [2,8,5] and LRU [8,2,5], but hits OPT [5,1,7].'], ['Totals after both appended accesses: FIFO 12, LRU 11, OPT 7.'])
  ], [ostep('22: Beyond physical memory, policies', 'vm-beyondphys-policy'), osc]),
  topic('vm-clock-anomaly', 'faults', 'Trace clock bits and demonstrate FIFO’s anomaly', [
    'Clock approximates recent use with a reference bit per frame and a circular hand. In this model, every access sets the frame bit to one. A replacement scans from the hand: clear a one and advance; replace the first zero; set its new bit to one and advance once more. Empty slots are initially filled in hand order.',
    'The hand and bits are part of the state. Showing only resident page numbers leaves the next victim ambiguous. The following trace uses the same thirteen references and three frames as the preceding comparison.'
  ], [
    trace('Clock slots are fixed; hand identifies the next slot to inspect', ['Step/page','Frame slots','Reference bits','Next hand/action'], [['1 / 2','[2,-,-]','100','1; fill'],['2 / 5','[2,5,-]','110','2; fill'],['3 / 2','[2,5,-]','110','2; hit'],['4 / 1','[2,5,1]','111','0; fill'],['5 / 5','[2,5,1]','111','0; hit'],['6 / 7','[7,5,1]','100','1; clear all, evict 2'],['7 / 2','[7,2,1]','110','2; evict 5'],['8 / 5','[7,2,5]','111','0; evict 1'],['9 / 1','[1,2,5]','100','1; clear all, evict 7'],['10 / 7','[1,7,5]','110','2; evict 2'],['11 / 2','[1,7,2]','111','0; evict 5'],['12 / 8','[8,7,2]','100','1; clear all, evict 1'],['13 / 5','[8,5,2]','110','2; evict 7']]),
    p('This workload yields 11 clock faults. Clock and FIFO happen to have equal fault counts on this trace; other traces distinguish them. At a full all-one state with no concurrent accesses, clock examines F bits to clear them and one more to select a victim. In a live system, references can set bits while scanning, so bounds and locking must match the implementation. Hardware accessed-bit sampling also requires the architecture’s translation-cache rules when software clears bits.',
      'More frames do not guarantee fewer FIFO faults. Consider the independently checked stream `1,3,0,2,1,3,2,4,3,1,1,1,3,0,3,4,2,4`. With three frames, FIFO faults nine times. With four frames, it faults ten times. The table shows arrival order, oldest first; repeated hits never move a page.'),
    trace('FIFO anomaly with an original eighteen-access stream', ['Step/page','Three-frame FIFO','Four-frame FIFO'], [['1 / 1','F [1]','F [1]'],['2 / 3','F [1,3]','F [1,3]'],['3 / 0','F [1,3,0]','F [1,3,0]'],['4 / 2','F [3,0,2]','F [1,3,0,2]'],['5 / 1','F [0,2,1]','H [1,3,0,2]'],['6 / 3','F [2,1,3]','H [1,3,0,2]'],['7 / 2','H [2,1,3]','H [1,3,0,2]'],['8 / 4','F [1,3,4]','F [3,0,2,4]'],['9 / 3','H [1,3,4]','H [3,0,2,4]'],['10 / 1','H [1,3,4]','F [0,2,4,1]'],['11 / 1','H [1,3,4]','H [0,2,4,1]'],['12 / 1','H [1,3,4]','H [0,2,4,1]'],['13 / 3','H [1,3,4]','F [2,4,1,3]'],['14 / 0','F [3,4,0]','F [4,1,3,0]'],['15 / 3','H [3,4,0]','H [4,1,3,0]'],['16 / 4','H [3,4,0]','H [4,1,3,0]'],['17 / 2','F [4,0,2]','F [1,3,0,2]'],['18 / 4','H [4,0,2]','F [3,0,2,4]'],['Total','9 faults','10 faults']]),
    p('Exact LRU has a stack inclusion property: the F most recently used distinct pages are a subset of the F+1 most recently used pages after the same reference prefix. Therefore increasing capacity cannot turn an LRU hit into a miss for that prefix. FIFO lacks that inclusion relationship because capacity changes the arrival history. OPT also has a nonincreasing minimum fault count: extra capacity can always reproduce a smaller cache’s choices if necessary.'),
    exercise('Explain the anomaly’s last fault', 'Immediately before the last access to page 4, the three-frame queue is [4,0,2] and the four-frame queue is [1,3,0,2].', ['Explain the hit/miss difference without using total memory size as a reason.', 'Compute the FIFO victim in the four-frame case.', 'Explain why this does not prove three frames are universally faster.'], ['The smaller queue retains page 4, while the larger queue evicted it earlier because its different admission history put it first in line.', 'The four-frame queue evicts page 1 and becomes [3,0,2,4].', 'This is one trace and one policy. Different traces, I/O costs, and policies can give different results.'], ['Last access: three-frame hit, four-frame fault.'])
  ], [ostep('22: Beyond physical memory, policies', 'vm-beyondphys-policy'), osc]),
  topic('vm-working-set-thrashing', 'faults', 'Connect replacement to working sets and thrashing', [
    'A replacement policy chooses among candidates; allocation policy determines how many frames each process may retain and which processes may compete for them. Under local replacement, a process evicts from its assigned resident set. Under global replacement, it can take a frame previously occupied by another process.',
    'The working set over a window is the set of distinct pages referenced during that window. Define the window before reporting its size: it might be the last Δ references or a chosen amount of execution time. This estimates active demand during the selected interval.'
  ], [
    trace('A four-reference window over 1,2,1,3,4,3,4,5', ['Prefix ends at step','Last four references','Working set'], [['4','1,2,1,3','{1,2,3}: size 3'],['5','2,1,3,4','{1,2,3,4}: size 4'],['6','1,3,4,3','{1,3,4}: size 3'],['7','3,4,3,4','{3,4}: size 2'],['8','4,3,4,5','{3,4,5}: size 3']]),
    p('Thrashing occurs when the system spends much of its effort repeatedly recovering pages that active computation needs again soon. A process cyclically reading pages A, B, C, D with only three frames faults on every access after warmup under LRU. Four frames reduce later accesses to hits once all four pages are resident. The key demand is the reuse interval relative to available capacity.',
      'Global replacement improves sharing of unused capacity, but one scanning workload can displace another process’s hot pages. Local replacement isolates that interference but can strand spare frames in a process with little current demand. Practical systems combine accounting, priorities, reclaim domains, and pressure feedback. A teaching simulator should expose both the victim policy and the allocation policy so their effects can be measured separately.',
      'Suppose three active processes have working-set estimates of 6, 5, and 4 frames, while only 12 pageable frames remain after kernel and pinned memory. Their estimated demand is 15. Changing FIFO to LRU cannot make 15 simultaneous required frames fit in 12. The system can reduce concurrency, grow available memory, reclaim genuinely inactive pages, or accept additional faults. The estimate may change with program phase, so policy needs observation over time.',
      'Page-fault-frequency control uses a process’s recent fault rate to adjust its resident allocation. A high rate can suggest granting frames; a low rate can suggest reclaiming some. This feedback must distinguish cold start, streaming access, and recurring reuse. A one-pass scan may fault frequently without benefiting from retaining every page after its only use.',
      'Keep prefetch and writeback separate from victim selection. Prefetch can overlap I/O for predictable access but waste bandwidth and frames when predictions fail. Background writeback can create clean eviction candidates before urgent pressure. Pinning, shared mappings, and dirty state restrict the candidate set and mean that counting all resident pages as equally reclaimable overstates available capacity.'),
    exercise('Diagnose a memory-pressure graph', 'CPU utilization falls while storage utilization and major faults rise. The scheduler responds by making more processes runnable.', ['Explain a possible positive feedback loop.', 'Give one observation that distinguishes a one-pass scan from thrashing.', 'Choose a controlled experiment for the three-process 15-frame demand example.'], ['Low CPU utilization can result from waiting for page I/O. Adding active processes increases competing working sets, causing more eviction and more waiting.', 'Track whether recently evicted pages return quickly; repeated reuse faults indicate insufficient resident capacity more directly than a raw fault count.', 'Temporarily suspend one process or increase pageable capacity, then compare useful work, fault rate, and I/O. Keep the workload and replacement policy fixed.'], ['The proposed experiment separates capacity pressure from policy changes.'])
  ], [osc, ostep('22: Beyond physical memory, policies', 'vm-beyondphys-policy')])
);

memoryHandbook['kernel-heap'].push(
  topic('heap-fit-policies', 'fragmentation', 'Compare first fit, next fit, best fit, and worst fit', [
    'A variable-sized allocator keeps free holes and chooses one large enough for a request. Define size consistently: an implementation usually searches using an aligned total block size that includes metadata. The abstract trace below measures usable hole units and deliberately omits metadata to isolate the choice policy.',
    'Start with four holes in address order: A = 96, B = 224, C = 80, D = 320. Process requests 64, 160, 96, and 256. Splitting keeps a hole’s remainder at its original position in the list. For this arithmetic model every positive remainder is representable.'
  ], [
    table('Define the search rule before tracing', ['Policy','Selection rule','Work with an unsorted linked list'], [['First fit','First adequate hole from the list head','O(H) worst case; may stop early'],['Next fit','First adequate hole from the saved cursor, wrapping once','O(H) worst case; cursor state matters'],['Best fit','Smallest adequate hole; break ties by address','O(H) full scan unless indexed by size'],['Worst fit','Largest adequate hole; break ties by address','O(H) full scan unless indexed by size']]),
    trace('Independent policy runs; next fit starts at C and resumes at the remainder', ['Request','First fit','Next fit','Best fit','Worst fit'], [['64','A: 96 → 32','C: 80 → 16','C: 80 → 16','D: 320 → 256'],['160','B: 224 → 64','D: 320 → 160','B: 224 → 64','D: 256 → 96'],['96','D: 320 → 224','D: 160 → 64','A: 96 → 0','B: 224 → 128'],['256','Fails; largest hole 224','Fails; largest hole 224','D: 320 → 64','Fails; largest hole 128'],['Final holes A,B,C,D','32,64,80,224','96,224,16,64','0,64,16,64','96,128,80,96']]),
    p('First fit has 400 free units before the last request, but cannot provide 256 contiguous units because its largest hole is 224. This is external fragmentation. Best fit happens to preserve D for the last request in this workload. That result does not establish a universal ranking: best fit can create many tiny remainders, worst fit can consume the only large block needed later, and next fit changes behavior with cursor position.',
      'The free-list order is an algorithm parameter. First fit on an address-ordered list behaves differently from first fit on a size-ordered list. Sorting by increasing size makes the first adequate element a best-fit choice, but maintaining that order has a cost. A balanced tree keyed by size can support logarithmic selection; coalescing still needs a way to find physical neighbors, often separate address metadata.',
      'A real remainder must be large enough to represent a future free block. Suppose a block requires a 16-byte header and a 16-byte minimum payload. A 16-byte leftover cannot become an independent block. The allocator absorbs it into the allocation, increasing internal waste. Adding this rule can change subsequent trace outcomes, so do not apply a minimum-size rule silently halfway through an experiment.',
      'Measure both failure behavior and overhead. Useful metrics include total free bytes, largest free block, live requested bytes, live reserved block bytes, metadata bytes, and search length. The ratio between total free bytes and largest hole describes one snapshot of external fragmentation; it cannot predict every future request distribution. Record the allocation/free sequence and alignment requirements along with the metric.'),
    exercise('Change one assumption', 'Reuse the four-hole trace, but require every split remainder to be at least 32 units.', ['Determine what best fit does with the first 64-unit request in hole C = 80.', 'Recalculate its final free space after all four requests.', 'Explain which kind of fragmentation increases.'], ['The 16-unit remainder is too small, so best fit consumes all 80 units of C.', 'B leaves 64, A is consumed exactly, and D leaves 64. Final free space is 128 units.', 'The first allocation has 16 units of internal waste. The original abstract trace retained that space as a free hole.'], ['Final best-fit free total = 128.', 'First allocation internal waste = 16.'])
  ], [ostep('17: Free-space management', 'vm-freespace'), osc]),
  topic('heap-alignment-overflow', 'defense', 'Prove allocation arithmetic before editing a free list', [
    'An allocator receives a byte count and must turn it into a representable aligned block size. Overflow can make a huge request appear small, causing the caller to write beyond the returned object. Arithmetic checks belong before any list mutation so failure preserves the arena state.',
    'Use an explicit teaching layout: a 16-byte header, payload aligned to 16 bytes, and a minimum 16-byte payload. The total block size is header plus rounded payload. This code uses uint32_t sizes even on a host where native size_t is wider.'
  ], [
    code('Checked 32-bit size normalization', 'c', '#include <stdint.h>\n#include <stdbool.h>\n\nbool block_size(uint32_t requested, uint32_t *out) {\n    const uint32_t header = 16, mask = 15;\n    if (requested == 0) return false;\n    if (requested > UINT32_MAX - mask) return false;\n    uint32_t payload = (requested + mask) & ~mask;\n    if (payload > UINT32_MAX - header) return false;\n    *out = header + payload;\n    return true;\n}\n\nbool array_bytes(uint32_t count, uint32_t size, uint32_t *out) {\n    if (size != 0 && count > UINT32_MAX / size) return false;\n    *out = count * size;\n    return true;\n}', [
      'Both functions require a non-null writable out pointer and preserve it on failure. block_size defines zero as an invalid request for this kernel API.',
      'Adding mask rounds upward after clearing the low four bits. The first guard proves that addition cannot wrap.',
      'A separately checked header addition is essential: a rounded payload can fit while the full block cannot.',
      'The multiplication guard divides only when size is nonzero. A zero-sized array produces zero bytes under this helper; the allocation API may then reject or specially handle zero.'
    ]),
    trace('Checked block sizes', ['Requested payload','Rounded payload','Total block / result'], [['1','16','32'],['16','16','32'],['17','32','48'],['0','No calculation','Rejected; output unchanged'],['0xFFFFFFF0','0xFFFFFFF0','Rejected because adding 16 overflows'],['0xFFFFFFFF','No calculation','Rejected before rounding']]),
    p('Alignment of the total size is insufficient unless the arena base and header layout also preserve payload alignment. With a 16-byte-aligned block base and a 16-byte header, the returned payload begins on a 16-byte boundary. If the header were 12 bytes, a correctly rounded total would still return a misaligned payload. State alignment guarantees in the allocator interface.',
      'For arbitrary power-of-two alignment a, prove that a is nonzero and `(a & (a - 1)) == 0` before using bit masks. A general aligned allocator may need extra padding plus a record of the original block base so free can recover the allocation correctly. Returning an adjusted interior pointer without a recovery scheme breaks deallocation.',
      'Bounds checks also need subtraction-based proofs. To verify that an object of length n fits in an arena [base,end), first establish p >= base and p <= end, then test n <= end - p. Computing p + n first can wrap. For a C implementation, avoid creating out-of-bounds pointers during the check; represent arena positions as bounded integer offsets and form pointers only after validation.',
      'Successful arithmetic does not guarantee available memory. After normalizing the request, the allocator still checks capacity, block state, and minimum remainder size. Keep these failures distinct in diagnostics: invalid request, arithmetic overflow, no suitable hole, and backing-page allocation failure answer different debugging questions.'),
    exercise('Audit a calloc-like request', 'A caller requests 0x40000001 elements of four bytes each with a 32-bit allocation size.', ['Compute the mathematical product.', 'Show the wrapped 32-bit product that unchecked arithmetic would produce.', 'Explain why the division guard rejects it.'], ['The mathematical product is 0x100000004, or 4,294,967,300.', 'Modulo 2^32, the product becomes 4, which would allocate space for only one element.', 'UINT32_MAX / 4 is 0x3FFFFFFF. The requested count exceeds that bound, so the multiplication is rejected before it executes.'], ['Overflow guard rejects the request.', 'Unchecked result would be 4.'])
  ], [ostep('14: Memory API', 'vm-api'), ostep('17: Free-space management', 'vm-freespace')]),
  topic('heap-split-boundary-tags', 'implementation', 'Split and coalesce blocks while preserving arena structure', [
    'An arena is a sequence of blocks covering a known virtual interval. A block header records its total size and allocation state. If sizes include metadata, the next block begins at current_offset + current_size. That invariant lets an implicit-list allocator walk the entire arena without separate next pointers.',
    'A first implementation can scan physical neighbors to coalesce. Boundary tags later add a footer or previous-size information so the predecessor can be located directly. Distinguish the physical neighbor relation from free-list links: consecutive nodes in a free list can be far apart in the arena.'
  ], [
    trace('256-byte arena, 16-byte headers, 16-byte alignment, minimum block 32', ['Operation','Block sequence by total size','Reason'], [['Initial','Free 256','One block spans the arena.'],['Allocate A payload 17','A 48 | Free 208','Round payload to 32, add header 16.'],['Allocate B payload 33','A 48 | B 64 | Free 144','Round payload to 48, add header 16.'],['Allocate C payload 16','A 48 | B 64 | C 32 | Free 112','Exact aligned payload plus header.'],['Free B','A 48 | Free 64 | C 32 | Free 112','Both adjacent allocated blocks prevent merging.'],['Free A','Free 112 | C 32 | Free 112','Merge neighboring free blocks 48 + 64.'],['Free C','Free 256','Merge predecessor 112, current 32, successor 112.']]),
    code('Bounded implicit-list allocator model with integer offsets', 'c', '#include <stdint.h>\n#include <stdbool.h>\n#define ARENA_BYTES 256u\n#define HEADER 16u\n#define MIN_BLOCK 32u\n#define FAILURE UINT32_MAX\n/* Metadata model: header entries exist only at block starts.\n   Returned offsets model payload addresses; no actual arena bytes here. */\nstatic uint32_t size_at[ARENA_BYTES / 16] = { ARENA_BYTES };\nstatic bool used_at[ARENA_BYTES / 16];\n\nuint32_t take_block(uint32_t need) {\n    if (need < MIN_BLOCK || (need & 15u) || need > ARENA_BYTES)\n        return FAILURE;\n    for (uint32_t pos = 0; pos < ARENA_BYTES; ) {\n        uint32_t i = pos / 16, size = size_at[i];\n        if (size < MIN_BLOCK || (size & 15u) ||\n            size > ARENA_BYTES - pos) return FAILURE;\n        if (!used_at[i] && size >= need) {\n            if (size - need >= MIN_BLOCK) {\n                uint32_t next = (pos + need) / 16;\n                size_at[next] = size - need;\n                used_at[next] = false;\n                size_at[i] = need;\n            }\n            used_at[i] = true;\n            return pos + HEADER;\n        }\n        pos += size;\n    }\n    return FAILURE;\n}\n\nbool release_block(uint32_t payload) {\n    uint32_t pos = 0, prev = FAILURE;\n    while (pos < ARENA_BYTES) {\n        uint32_t i = pos / 16, size = size_at[i];\n        if (size < MIN_BLOCK || (size & 15u) ||\n            size > ARENA_BYTES - pos) return false;\n        if (pos + HEADER == payload) {\n            if (!used_at[i]) return false;\n            used_at[i] = false;\n            uint32_t next = pos + size;\n            if (next < ARENA_BYTES && !used_at[next / 16])\n                size_at[i] += size_at[next / 16];\n            if (prev != FAILURE && !used_at[prev / 16])\n                size_at[prev / 16] += size_at[i];\n            return true;\n        }\n        prev = pos;\n        pos += size;\n    }\n    return false;\n}', [
      'This complete single-threaded metadata simulation represents allocator state without backing payload storage. take_block accepts an already checked total block size. Separate arrays represent headers so the arithmetic can be studied without pointer aliasing or alignment hazards.',
      'take_block walks only current block starts. On splitting, the remainder is initialized before marking the selected block allocated. A remainder below 32 is absorbed.',
      'release_block searches for an exact payload boundary, so an interior offset and a duplicate free fail. It merges the successor first, then adds the combined size to a free predecessor.',
      'Stale array entries inside merged blocks are unreachable because iteration advances by the new outer size. The model assumes valid allocator-owned metadata and external serialization; it is not hardened against arbitrary metadata corruption.',
      'Both operations are O(B) in the number of blocks because they walk the implicit list. A boundary tag can make neighbor lookup constant time, while an explicit free list reduces allocation scanning to free blocks.'
    ]),
    p('Boundary-tag coalescing has four cases: neither neighbor free, only previous free, only next free, or both free. Remove all free neighbors from their free lists before combining sizes, then insert the merged block once. Update the surviving header and footer or successor’s previous-size field. Forgetting to unlink an absorbed free node leaves a list entry pointing into a larger free block, allowing overlapping allocations later.',
      'Footers cost space. An optimized layout can keep previous-size data only when needed and encode a previous-in-use flag in alignment bits. That optimization complicates invariants. Begin with a layout where every block boundary can be inspected, validate it after each mutation, and measure overhead before removing metadata.',
      'The arena checker should prove that every size is aligned and at least the minimum, every step stays within the arena, the final block ends exactly at the arena boundary, no two adjacent blocks remain free after eager coalescing, and every explicit free-list node corresponds to exactly one free physical block. These are behavioral invariants that catch corruption across many sequences.'),
    exercise('Reproduce the split/coalesce trace', 'Use the model above and normalized total sizes 48, 64, and 32.', ['Find the three returned payload offsets.', 'Free the middle, first, and last allocations in that order.', 'Try to free offset 17 and the final allocation a second time.'], ['The payload offsets are 16, 64, and 128 because block starts are 0, 48, and 112.', 'The free sequence yields the listed states and finally one free 256-byte block.', 'Offset 17 is not a payload boundary. A second free also fails because the arena walk no longer finds that allocated block.'], ['Returned offsets: 16, 64, 128.', 'Final block: free size 256 at offset 0.'])
  ], [ostep('17: Free-space management', 'vm-freespace')]),
  topic('heap-slab-object-caches', 'layers', 'Build small-object caches above page allocation', [
    'Repeated kernel objects often have a stable size: task records, inode records, timers, or I/O descriptors. A slab-style cache obtains one or more pages, divides them into aligned object slots, and keeps a free-slot structure. It avoids performing a variable-hole search for every object.',
    'For an original layout, reserve 64 metadata bytes in a 4096-byte slab. Objects need 96 bytes aligned to 16. The stride is 96, so floor((4096 - 64) / 96) = 42 objects fit exactly into the remaining 4032 bytes.'
  ], [
    table('Object size changes the packing', ['Requested object','Aligned stride','Slots after 64-byte metadata','Unused tail'], [['96 bytes, align 16','96','42','0'],['100 bytes, align 16','112','36','0'],['80 bytes, align 64','128','31','64']]),
    p('Keep slabs on empty, partial, and full lists. Allocation takes a free slot from a partial slab or obtains a new slab when allowed. Freeing the last live object can move a slab to the empty list. A reclaim policy may return empty slabs to the PMM. A partially occupied slab cannot be released while any object in it remains live, even if its total free space exceeds a page.',
      'A cache may initialize invariant object state once when constructing slots, then reset per-use fields on allocation or release. Define the lifecycle carefully: stale references, old credentials, linked-list membership, and lock state must never leak into a new logical object. Reusing initialized storage does not mean every old field is safe to retain.',
      'A free-slot link can live inside an unused object. The link belongs to allocator metadata only while that slot is free. Debugging modes can fill freed contents with a recognizable pattern, quarantine recently freed slots, or add red zones. Those checks increase memory cost and cannot prove that all stale pointers are gone; they make common misuse easier to detect.',
      'Per-CPU object caches reduce shared-lock traffic but retain memory outside the central partial-slab lists. A remote free may need a queue back to the owning CPU or a carefully synchronized slab update. Pressure handling must drain caches consistently before deciding how much memory is reclaimable. An interrupt-context allocation can use a prefilled bounded cache, while replenishment occurs later in a context allowed to allocate backing pages.',
      'There are several distinct wastes: padding from object size to slot stride, slab metadata, unused tail bytes, and free slots stranded in slabs with live objects. A workload leaving one 96-byte object in each of ten 4 KiB slabs retains 40 KiB of backing memory for 960 bytes of requested live objects, plus whatever metadata convention is used. Object caches improve common-case operations but still need occupancy measurements and reclaim policy.'),
    exercise('Calculate a cache budget', 'A cache uses 4096-byte slabs, 64 bytes of metadata, and 112-byte slots for 100-byte objects. It needs 73 live objects.', ['Find the minimum number of slabs.', 'Compute live-requested bytes, slot bytes for live objects, and total slab bytes.', 'Explain why freeing 37 arbitrary objects may fail to release a slab.'], ['Each slab fits 36 slots, so 73 objects require three slabs.', 'Requested bytes are 7300; live slot bytes are 8176; backing slab bytes are 12288.', 'The remaining 36 objects may be scattered across all three slabs, leaving every slab partially occupied. Releasing a slab requires all of its objects to be free.'], ['Three slabs; 12288 backing bytes.'])
  ], [kernelMemory, ostep('17: Free-space management', 'vm-freespace')]),
  topic('heap-malloc-brk-mmap', 'brk', 'Separate malloc objects, virtual regions, and physical frames', [
    'malloc is typically a userspace library operation. It divides already owned virtual memory into objects and requests more virtual memory from the kernel when necessary. The kernel’s physical allocator works in frames; its virtual-memory layer maps those frames; the user allocator manages bytes inside those mappings.',
    'A program break describes one logical endpoint of a data-region allocation. brk requests a new endpoint; an sbrk-style interface requests a signed change and conventionally returns the old break on success. mmap-style allocation creates a separate virtual region with explicit length and permissions.'
  ], [
    trace('A small allocation can cross several layers only when needed', ['Layer','Action','Ownership unit'], [['Application','malloc(24)','24 requested bytes'],['User allocator','Select a size class or split an existing free block','Aligned object plus allocator metadata'],['Virtual-memory API, if arena expansion needed','Grow a break region or create a mapping','Virtual byte interval / page-rounded coverage'],['Fault handling, if allocation is lazy','Supply zero-filled backing on first access','One or more physical frames'],['PMM','Take eligible free frames','Physical frame ownership']]),
    p('Freeing an object usually returns it to the userspace allocator. It may be retained for future allocations even though the process no longer uses it. The allocator can return whole suitable mappings or trim the top of a break region according to its policy. A hole in the middle of the break region cannot simply lower the break past live objects above it.',
      'Logical break movement and page mapping occur at different granularities. Growing a break from 0x2003 to 0x2008 changes five logical bytes but may require no new mapped page if [0x2000,0x3000) is already present. Shrinking within the same page must preserve still-valid bytes. Removing a whole trailing page requires revocation and TLB synchronization; later reallocation must satisfy the zeroing and data-isolation contract.',
      'A returned virtual pointer does not always imply that every backing frame has already been allocated. Lazy allocation can defer that cost until access. The system must specify its commitment and out-of-memory policy. Measure virtual reservation, resident memory, and allocator-held free bytes separately when diagnosing an apparent memory leak.',
      'A kernel heap repeats the same layering inside the kernel but has different constraints. Its callers may need immediate availability, fixed physical alignment, nonblocking operation, or device-accessible memory. A generic kmalloc-like interface must state which promises it makes. A virtually contiguous buffer assembled from scattered frames is unsuitable for a device requiring one contiguous physical range unless a supported DMA/IOMMU mechanism provides the needed view.'),
    exercise('Where did the memory go?', 'A process obtains a 64 KiB arena, allocates ten 128-byte objects, and then frees all ten. Its resident memory does not decrease.', ['Give a valid allocator explanation.', 'State what evidence would distinguish retained free space from unreachable live allocations.', 'Explain why calling free does not necessarily invoke a kernel operation.'], ['The library may retain the arena and its backing pages for later objects.', 'Inspect allocator live-object accounting and free-bin/arena statistics along with process mappings and resident-page counts.', 'Returning a block to a userspace free list can be completed entirely in userspace without changing mappings.'], ['The answer separates allocator ownership from process residency.'])
  ], [ostep('14: Memory API', 'vm-api'), ref('Linux malloc manual', 'https://man7.org/linux/man-pages/man3/malloc.3.html', 'Allocation behavior'), ref('Linux brk manual', 'https://man7.org/linux/man-pages/man2/brk.2.html', 'Program break semantics')])
);

memoryHandbook['user-mode'].push(
  topic('user-address-space-contract', 'contract', 'Make the privilege boundary an address-space contract', [
    'Entering ring 3 changes the privilege of instruction execution, but memory isolation depends on the mappings that execution can reach. Kernel code, kernel stacks, page tables, and device control regions must remain supervisor-only. A user page needs suitable user permissions at every level of its translation path.',
    'Choose a concrete teaching layout: user addresses lie below 0xC0000000, and the upper range is reserved for kernel mappings. This boundary is an OS convention. The hardware enforces entry permissions; it does not know that the number 0xC0000000 has special meaning to the allocator.'
  ], [
    table('State needed before the first return to ring 3', ['Resource','Required property','Failure when absent'], [['User entry page','Present, user-accessible, intended code bytes','Instruction fetch faults immediately.'],['User stack','Present writable user pages, checked initial ESP','Pushing a return address or local value faults.'],['Kernel entry stack','Supervisor writable stack selected on privilege entry','An interrupt or system call cannot safely save state.'],['Descriptor and interrupt metadata','Valid privileged GDT/TSS/IDT state','Privilege transitions raise exceptions or fail catastrophically.'],['Kernel mappings','Accessible at ring 0, denied to ring 3','User code can otherwise read or overwrite kernel state.'],['Guard pages','Deliberately absent boundary pages','Overflow can otherwise silently overwrite neighboring memory.']]),
    p('In this 32-bit x86 design, the TSS supplies the ring-0 SS0:ESP0 stack used when an interrupt or trap changes privilege from user mode. Keep that stack mapped in whichever address space is active at the transition, and update the appropriate per-thread or per-CPU state according to the scheduler design. The user stack must never become the trusted stack for saving kernel entry state.',
      'An IRET frame for returning from ring 0 to ring 3 contains the target EIP, CS, EFLAGS, ESP, and SS in the architecture-defined order. The chosen selectors need valid privilege metadata, and the user mappings must cover the instruction and stack addresses. Control EFLAGS deliberately, including interrupt enable and I/O privilege. A page-table permission bug cannot be repaired by a correct IRET frame alone.',
      'A system call transports integer arguments and pointers from an untrusted context into a privileged one. A user-provided address is a request to access memory under user authority. Validate its range, requested access direction, and mapping lifetime before using it. For a read system call that writes bytes into a user buffer, the kernel needs user-write permission; for a write system call that reads user bytes, it needs user-read permission.',
      'The kernel often shares its own upper mappings among process page directories so entry code remains reachable across context switches. Sharing those physical page-table frames requires shared ownership and synchronized updates. The user portion differs per process, and user permission must never accidentally propagate into a kernel leaf. Test ring-3 read and write attempts against representative kernel ranges as well as successful user execution.'),
    exercise('Trace an interrupt at ring 3', 'A user program runs with ESP = 0xBFFFEF00. Its TSS ESP0 points to 0xC0400000, but the page immediately below that address is absent in its active directory.', ['Explain why the valid user stack cannot save this transition.', 'Identify the mapping that must be repaired.', 'State when the scheduler should establish that state.'], ['A privilege-changing interrupt uses the trusted kernel stack selected by the TSS; it cannot substitute the user stack.', 'Map a supervisor writable kernel stack region below the configured top, with the needed capacity and deliberate guard.', 'Before the thread is allowed to execute at ring 3 or receive an entry that depends on that stack.'], ['Kernel entry stack is mapped in the active address space before user execution.'])
  ], [intel]),
  topic('user-buffer-range-lifetime', 'copy', 'Validate every user page and preserve it during copying', [
    'A buffer describes an interval through a starting pointer and a byte length. A two-byte request beginning at address 0x1FFF touches two pages. Checking only the first address misses the permission or presence of the second page. First prove that the whole numerical interval is inside the allowed user range, then check every touched page.',
    'The helper below models a 32-bit address space with 4 KiB pages and exclusive USER_TOP = 0xC0000000. It validates addresses arithmetically and delegates effective mapping permissions to has_user_page. It does not copy bytes or guarantee that mappings remain unchanged afterward.'
  ], [
    code('Overflow-safe complete-page coverage', 'c', '#include <stdint.h>\n#include <stdbool.h>\n#define USER_TOP 0xC0000000u\nextern bool has_user_page(uint32_t page, bool write);\n\nbool user_range(uint32_t p, uint32_t n, bool write) {\n    if (n == 0) return p <= USER_TOP;\n    if (p >= USER_TOP || n > USER_TOP - p) return false;\n    uint32_t first = p & ~4095u;\n    uint32_t last = (p + n - 1u) & ~4095u;\n    for (uint32_t page = first; ; page += 4096u) {\n        if (!has_user_page(page, write)) return false;\n        if (page == last) return true;\n    }\n}', [
      'The zero-length case is a declared API policy: no bytes are touched, and the boundary itself is acceptable. Other APIs can choose a different policy, but must specify it.',
      'The subtraction test proves p + n stays at or below USER_TOP before the addition is used. The n - 1 expression is reached only for nonzero n.',
      'Both first and last are aligned page bases. The loop tests the last page before incrementing, so it cannot wrap beyond the validated user interval.',
      'has_user_page must check effective permissions across the paging hierarchy for the requested access. A PTE USER bit by itself is insufficient.',
      'Time is O(number of touched pages); no allocation is performed. A real copy path additionally needs a mapping-lifetime and fault-recovery protocol.'
    ]),
    trace('Boundary cases under the declared policy', ['Pointer / length','Pages inspected','Result'], [['0x1FFF / 2','0x1000 and 0x2000','Fails if either page lacks requested access.'],['0xBFFFFFFF / 1','0xBFFFF000','Potentially valid final user byte.'],['0xBFFFFFFF / 2','None','Rejected by interval bounds.'],['0xC0000000 / 0','None','Accepted empty interval.'],['0xFFFFFFF0 / 32','None','Rejected before any wrapping addition.']]),
    p('Validation followed by an unlocked memcpy has a time-of-check/time-of-use race. Another thread can unmap the region, change permissions, or replace its backing frame after the checks. A teaching kernel can serialize mapping changes over a bounded copy, while a more capable kernel can pin the relevant pages or use a fault-aware user-copy mechanism with an explicit partial-copy result. Each approach has locking and blocking constraints.',
      'Pinning means retaining references that prevent backing storage from disappearing during the operation. It does not automatically freeze the bytes: another user thread may still modify a writable buffer. For a control structure containing lengths and pointers, copy the bounded structure into kernel memory once, validate that snapshot, and avoid repeatedly trusting mutable user fields. For strings, apply a maximum length and handle page boundaries while searching for the terminator.',
      'Output copies need the opposite direction of permission. Before storing into user memory, confirm the destination is writable under user authority even though the store instruction runs in ring 0. CR0.WP helps enforce read-only mappings in the basic hardware model, but software validation still supplies the user-region and lifetime policy. Advanced architectures have additional supervisor/user access controls that the copy routines must follow.',
      'Specify failure effects. A copy may fail after transferring a prefix if a later page faults. The API can return bytes not copied, bytes copied, or an error with a documented partial-effect rule. Never label a partially initialized kernel structure valid merely because the first portion copied successfully.'),
    exercise('A mutable system-call request', 'A user structure contains {pointer, length}. The kernel checks length, then reads pointer and length again when starting a copy. Another user thread may modify the structure.', ['Describe a harmful race.', 'Give a snapshot-based fix.', 'Explain which separate race remains after taking the snapshot.'], ['The second length can grow beyond the checked bound, or the pointer can change to a different region.', 'Copy the fixed-size request into kernel-owned storage using the user-copy protocol, then validate and use only that snapshot.', 'The referenced buffer’s mapping and contents can still change. Mapping lifetime and any required content snapshot must be handled separately.'], ['User-controlled length is checked and used from the same snapshot.'])
  ], [intel, ref('Linux memory-management APIs', 'https://docs.kernel.org/core-api/mm-api.html', 'User page access and memory lifetime')])
);

memoryHandbook['elf-loader'].push(
  topic('elf-validate-load-contract', 'validate', 'Validate an ELF image before allocating its address space', [
    'An executable file is input to a privileged parser. Every offset, count, size, and virtual address must be checked before it influences allocation or copying. Loading according to program headers gives the runtime image; section headers primarily describe linking and other file organization.',
    'Define a bounded first loader: little-endian ELF32 for i386, a supported ELF version, fixed-address ET_EXEC images, ordinary PT_LOAD segments, and a chosen user virtual range. Explicitly reject interpreter-dependent or relocation-dependent images until those mechanisms exist. A successful magic-number check alone establishes very little.'
  ], [
    table('Header validation checklist with its reason', ['Field or relation','Required check','Why'], [['Class, byte order, machine, version','Match the implemented ELF32/i386 contract','Prevents interpreting a different binary layout.'],['Program-header size','Match the supported Elf32_Phdr size, 32 bytes','Prevents advancing by an incompatible record size.'],['Program-header table extent','e_phoff <= file_size and count <= (file_size - e_phoff) / entry_size','Bounds the entire table without multiplication overflow.'],['Segment file extent','p_offset <= file_size and p_filesz <= file_size - p_offset','Prevents reading beyond the supplied file.'],['Memory extent','p_filesz <= p_memsz; virtual end fits user policy','Prevents undersized destination and wraparound.'],['Alignment','p_align is 0, 1, or a supported power of two; required congruence holds','Makes file-to-virtual placement consistent.'],['Entry address','Lies inside an accepted executable load region','Prevents transfer to an unrelated or absent address.']]),
    code('Bound a file slice before forming its pointer', 'c', '#include <stdint.h>\n#include <stdbool.h>\n\nbool file_slice(uint32_t offset, uint32_t length,\n                uint32_t file_size) {\n    return offset <= file_size && length <= file_size - offset;\n}\n\nbool user_segment(uint32_t start, uint32_t memory_size) {\n    const uint32_t low = 0x00001000u, top = 0xC0000000u;\n    if (memory_size == 0) return start >= low && start <= top;\n    return start >= low && start < top && memory_size <= top - start;\n}', [
      'These helpers implement a specific bounded teaching-loader policy. Page zero is excluded and USER_TOP is exclusive for nonempty segments.',
      'Subtraction occurs only after the left endpoint is known to be in range. A caller forms file pointers only after file_slice succeeds.',
      'Zero-sized segments are accepted only at policy-valid positions, then contribute no mappings. This policy can be stricter than the general file format.',
      'Successful interval checks do not validate ELF identity, flags, alignment, overlaps, or the entry point; those are separate checks.'
    ]),
    p('Decode file fields from bytes or use carefully defined structures whose widths and layout are verified. Do not cast arbitrary unaligned file data to a native host structure and assume ELF32 layout. A 64-bit host’s pointer width does not change the target file’s 32-bit fields. Preserve the distinction between file offsets, target virtual addresses, and kernel buffer pointers.',
      'Treat segment overlap as a planned feature. A simple first loader can reject overlapping page-rounded load regions, which simplifies per-page ownership and permission calculation. A more general loader must combine byte ranges that share a page, preserve both initialized contents, and choose permissions consistently with its security policy. Blindly zeroing each segment’s page range in sequence can erase bytes loaded for an earlier segment.',
      'Create a load plan after validation and before publication: sorted page ranges, file slices, zero-fill intervals, permissions, entry point, and stack reservation. Check those regions against the kernel split, guard pages, and other mappings. Keep the new address space private until all mandatory resources exist so failure can tear it down without damaging the currently running process.'),
    exercise('Catch two arithmetic attacks', 'A file is 0x3000 bytes long. Segment A has offset 0x2F00 and filesz 0x200. Segment B has vaddr 0xBFFFF000 and memsz 0x3000.', ['Apply the subtraction checks to both segments.', 'Explain why a wrapping addition-based comparison is a weaker implementation pattern.', 'State when allocation should begin.'], ['A has only 0x100 file bytes remaining, so 0x200 is rejected. B has only 0x1000 user bytes before USER_TOP, so 0x3000 is rejected.', 'An unchecked addition can wrap into a small value before the comparison. Subtraction after a validated start avoids that failure.', 'Begin allocating only after the complete load plan passes the declared checks, or use an equally rigorous provisional-resource rollback protocol.'], ['Both segments are rejected before copying.'])
  ], [elf]),
  topic('elf-map-file-zero-tail', 'pages', 'Map unaligned segments and zero exactly the required bytes', [
    'A PT_LOAD segment describes a byte interval in virtual memory and an initial prefix read from the file. It does not require one physically contiguous allocation. Allocate page-sized frames, map them to consecutive virtual pages, and copy each file intersection into the correct page offset.',
    'Use a worked segment with p_offset = 0x1123, p_vaddr = 0x08048123, p_filesz = 0x1450, p_memsz = 0x2A10, and p_align = 0x1000. The file and virtual offsets are both 0x123 modulo 4096, so their required congruence holds.'
  ], [
    trace('Derive all boundaries before writing bytes', ['Quantity','Calculation','Value'], [['File-backed virtual end','0x08048123 + 0x1450','0x08049573'],['Memory virtual end','0x08048123 + 0x2A10','0x0804AB33'],['First mapped page','align_down(0x08048123,4096)','0x08048000'],['Exclusive mapped-page end','align_up(0x0804AB33,4096)','0x0804B000'],['Frame count','(0x0804B000 - 0x08048000) / 4096','3'],['Required zero-fill tail','0x2A10 - 0x1450','0x15C0 bytes = 5568']]),
    table('Fill zeroed frames by virtual/file intersections', ['Virtual page','Initialized byte range','File source','Remaining policy'], [['0x08048000','[0x08048123,0x08049000), 0xEDD bytes','[0x1123,0x2000)','Leading 0x123 bytes remain zero under this teaching policy.'],['0x08049000','[0x08049000,0x08049573), 0x573 bytes','[0x2000,0x2573)','[0x08049573,0x0804A000) remains zero.'],['0x0804A000','No file-backed bytes','None','Required BSS ends at 0x0804AB33; remaining mapped tail stays zero.']]),
    p('A simple eager loader zeros each newly allocated frame before copying file bytes. This satisfies the required zero-filled segment tail and prevents exposure of a previous frame owner’s contents in padding bytes. The logical segment still ends at 0x0804AB33 even though hardware mapping extends to the next page boundary. Software region metadata records that difference.',
      'For any destination page interval [page,page+4096), intersect it with the initialized segment interval [vaddr,vaddr+filesz). If lo < hi, copy hi - lo bytes from file offset p_offset + (lo - vaddr) into the frame at offset lo - page. The validation phase must already have proved all source and destination extents. This formula naturally handles first and last partial pages without separate guessed lengths.',
      'Populate frames through a controlled kernel mapping while the new address space remains private. Final user mappings should receive their intended permissions after initialization. Avoid leaving writable aliases to supposedly immutable user code in a shared kernel mapping without a clear policy. In non-PAE mode, read/write and user/supervisor permissions are enforceable, while page-level execute denial is unavailable.',
      'Zero-fill and permissions become more complicated when two loadable segments share a page. The bounded loader used here rejects page-rounded overlap. To support it later, build one per-page plan that merges all initialized byte intervals before zeroing only the uncovered intervals and deciding permissions. Allocating the same virtual page twice and accepting whichever mapping was installed last loses data or leaks a frame.',
      'On failure, release the private address space with the same ownership machinery used for normal process teardown. Count every allocated data frame, page-table frame, stack frame, and retained file reference. If the old process continues after a failed exec, its mappings and register state must remain intact until the new image commits successfully.'),
    exercise('Move the initialized boundary', 'Keep the same vaddr and memsz, but change filesz to 0x0EDD.', ['Find the new file-backed virtual end.', 'Count how many pages receive file bytes.', 'Calculate the new required zero-fill length.'], ['0x08048123 + 0x0EDD = 0x08049000 exactly.', 'Only the first mapped page receives file bytes; the next two pages contain zero-filled segment bytes and padding.', '0x2A10 - 0x0EDD = 0x1B33, or 6963 bytes.'], ['File-backed end = 0x08049000.', 'Zero-fill length = 6963.'])
  ], [elf]),
  topic('elf-stack-break-commit', 'stack', 'Construct the initial stack and commit the process image', [
    'A valid executable mapping still needs an entry contract: initial registers, stack contents, argument encoding, stack alignment, and a way to exit. The exact layout belongs to the chosen ABI. A kernel cannot assume that jumping to a C main function with arbitrary ESP creates a valid call frame.',
    'The example below defines a deliberately small teaching ABI. At entry, ESP points to a 32-bit argc followed by argc 32-bit user pointers and a null pointer. Strings live at higher addresses in the same mapped page. There is no environment vector, auxiliary vector, or dynamic linker in this contract.'
  ], [
    table('One-page stack ending at 0xBFFFF000, arguments demo and x', ['User address','Bytes or word','Meaning'], [['0xBFFFEFFB','64 65 6D 6F 00','The string demo followed by NUL'],['0xBFFFEFF9','78 00','The string x followed by NUL'],['0xBFFFEFE0','0x00000002','argc = 2; initial ESP is 16-byte aligned'],['0xBFFFEFE4','0xBFFFEFFB','argv[0] pointer'],['0xBFFFEFE8','0xBFFFEFF9','argv[1] pointer'],['0xBFFFEFEC','0x00000000','argv terminator'],['0xBFFFD000 through 0xBFFFDFFF','Unmapped','Guard page below mapped stack [0xBFFFE000,0xBFFFF000)']]),
    p('The pointers stored in the stack are user virtual addresses. If the kernel copies strings through a temporary kernel alias, it must translate the resulting offset back to the user stack address before storing argv. Accidentally storing a kernel pointer makes the new program fault or exposes a privileged address. Count total string bytes, pointer words, padding, and guard policy before writing anything.',
      'The initial stack-pointer alignment must match the startup stub’s assumptions. The tiny ABI above chooses a 16-byte-aligned entry ESP. A real i386 System V process also needs its documented environment and auxiliary-vector layout, and the runtime’s call sequence must establish the alignment expected by compiled functions. Label a custom startup ABI clearly so learners do not mistake it for complete compatibility.',
      'Place the logical heap base above the loaded image according to a collision-free layout, and maintain a separate current break and maximum permitted range. Growing the break may map new pages or reserve lazy anonymous regions. A signed adjustment must be checked in a wider integer type so INT32_MIN is handled without negating it in 32-bit signed arithmetic.',
      'Commit is the point at which the new image becomes the process’s active address space and register context. Before commit, verify entry mapping, stack mapping, kernel entry stack, required kernel mappings, initial break, and ownership counts. After commit, retire the previous address space only after CPUs and software references can no longer use it. Loading an image and reclaiming the old one are two linked lifetime transitions.'),
    code('Checked signed adjustment for a 32-bit teaching break API', 'c', '#include <stdint.h>\n#include <stdbool.h>\n\nbool adjust_break(uint32_t old, int32_t delta,\n                  uint32_t base, uint32_t limit,\n                  uint32_t *out) {\n    if (base > limit || old < base || old > limit) return false;\n    int64_t candidate = (int64_t)old + (int64_t)delta;\n    if (candidate < (int64_t)base || candidate > (int64_t)limit)\n        return false;\n    *out = (uint32_t)candidate;\n    return true;\n}', ['out is writable and unchanged on failure. The inclusive logical endpoints are part of this helper’s contract.', 'Both operands are widened before addition. The result range fits int64_t for every uint32_t old and int32_t delta.', 'This helper only computes a candidate endpoint. Mapping, collision checks, lazy-region metadata, zeroing, and rollback must succeed before a real kernel commits the new break.']),
    exercise('Stack and heap boundaries', 'Use the displayed teaching stack and a break range [0x0804B000,0x09000000]. The current break is 0x0804C000.', ['Compute a -4096 adjustment.', 'Decide whether a second -4096 adjustment succeeds.', 'Explain why a large argument list must be checked before writing strings.'], ['The first candidate is 0x0804B000, exactly the base, so the arithmetic helper accepts it.', 'The next candidate is 0x0804A000, below base, so it fails without changing the break.', 'Without a total-size check, string and pointer writes can cross the mapped stack page, overlap each other, or enter the guard region.'], ['First adjustment succeeds at 0x0804B000.', 'Second adjustment fails.'])
  ], [elf, intel, ref('Linux brk manual', 'https://man7.org/linux/man-pages/man2/brk.2.html', 'Program break semantics')])
);
